INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('carnivorous-blue-fruit-tree', 'Carnivorous Blue Fruit Tree', 'plant', 'rifts', 0, 'Considered evil', '{"PS":"1D4+20","PP":"1D4+16"}', NULL, NULL, '6D6x10', '4D6x10', NULL, 'M.D.C. by location: Main Body 6D6x10; Tentacles (4D6+13 of them) 2D6+16 M.D.C. each. P.S. is the equivalent of Supernatural. Other attributes are irrelevant: it acts on instinct and reflex. P.P.E. 4D6x10 is the coral formation; each fruit holds another 3D6+13 P.P.E. A typical tree carries 6D6+13 fruits, a very well-fed one twice that.', NULL, NULL, '{"attacks":3,"strike":1,"dodge":2}', 'Three attacks per melee by bite or entanglement. +1 to strike, +4 to entangle with its tendrils, and +2 for a tendril to dodge, on top of any attribute bonuses. Impervious to Horror Factor, mind control and possession. 1D4+2 tendrils entangle in unison and hold until cut or the victim pulls free, which takes a combined Supernatural P.S. of 30 per three tendrils; each melee round the prey struggles, another 1D4+2 tendrils join in. It usually fights until every tentacle is gone, the prey is out of reach, or it is at zero M.D.C.', NULL, 'Takes half damage from cold and has no depth limit. The scent of its fruit carries over a six mile (9.6 km) radius and its magic aura over one mile (1.6 km). Heals 2D6 M.D.C. an hour and regrows a lost tentacle at full M.D.C. in 24 hours. Finds living things by motion, touch and heat. Tendrils look about 6 feet (1.8 m) long but reach 18 feet (5.5 m). It has 1D4+1 hidden mouths, and over 80% of its body is buried, so attackers who believe it dead have usually only hurt it. A held spell caster must spend double P.P.E. to cast, and each holding tendril drains 1D4 P.P.E. a melee round. Bite wounds cannot be Bio-Regenerated while even one tendril holds the victim. Normally one mouth bites at a time; whale-sized prey may face two or three mouths at once.', NULL, NULL, 'Coral bed covers 100-200 square feet (9.3 to 18.6 square meters)', '2,000-3,000 lbs (900 to 1350 kg)', NULL, 'Wild in the ocean; also grown at remote hideouts by rogue Biomancers and the Mauian Order', NULL, NULL, 'None; a plant and coral hybrid. Blue Death Fruit: sells for 1,000 credits each in Lemuria and far more elsewhere (8,000 credits has reportedly been paid). One fruit is a full meal; for 1D6+1 hours the eater tires at half the normal rate and gets +1 to strike and on initiative, +1 to save vs toxins and disease, and +2 to save vs undead mind control and vampire bite. A picked fruit stays fresh 1D6+11 years, has 1D4 S.D.C. and shrugs off bruising, cold and heat. Its 3D6+13 P.P.E. can be drawn like a talisman, including by Psi-Stalkers; once drained it tastes faintly sweet and metallic and shrivels in 1D4 hours.', 'Also called Blue Death, Hungry Blue Fruit Tree or Carnivorous Coral. An abandoned Biomancy creation that looks like a field of blue, tube-like coral stems with clusters of glowing, grapefruit-sized blue fruit at their bases. It was meant to bank the P.P.E. of dying prey in its fruit, dispose of organic waste and trap demons and sea monsters, but it cannot tell monster from person and ignores Lemurian empathy. Scent and aura draw fish, mages, dragons and supernatural beings in; tendrils then seize them and haul them to a buried maw, leaving no remains.', 'Rifts World Book 32: Lemuria p.34-35'),
('lemurian-ring-tailed-lemur', 'Lemurian Ring-Tailed Lemur', 'animal', 'rifts', 0, 'Anarchist in the wild; domesticated lemurs are generally the equivalent of Scrupulous (20%), Unprincipled (45%) or Anarchist (30%), but can be any', '{"IQ":"1D6+6","ME":"1D6+5","MA":"1D6+14","PS":"1D6+2","PP":"1D6+14","PE":"2D6+7","PB":"2D6+11","Spd":"2D6+12"}', '1D6+7', '1D6+9', NULL, '2D6+4', NULL, 'I.Q. is high animal intelligence. Spd 2D6+12 is on the ground and climbing; double when running and swinging through trees; swimming is half running speed. A.R.: not applicable.', NULL, NULL, '{"attacks":3,"initiative":2,"strike":1,"dodge":4,"roll":4}', '+3 on Perception Rolls, +2 on initiative, +1 to strike, +4 to dodge and +4 to roll with impact/fall.', 'Acrobatics 90%, Climbing 95%, swim 55%, track by scent 45%, detect or find plants by smell 65%.', 'Nightvision 200 feet (61 m) and good day vision. Jumps 8 feet (2.4 m) up and 12 feet (3.6 m) across. A keen nose lets it follow a scent trail and sniff out plants, and its hearing is exceptional. Like dogs and cats it reacts to magic and to supernatural presences.', NULL, NULL, 'Body 18 inches (0.4 m) long, plus a bushy tail of another 22 inches (0.56 m)', '3-7 lbs (1.3 to 3.1 kg)', '7-10 years in the wild; Familiars and domesticated lemurs live 2D6+15 years', 'Forests, jungles and Lemurian cities. Once found only in and around Madagascar and the African coast; now in parts of Africa and India and in every Lemurian city and outpost.', 'None as such; favored by Lemurians and some humans as pets and Familiars', 'Hunted by many large predators; dislikes the supernatural and is wary of people', 'None; an animal. Disposition: inquisitive, playful and loyal. Value: 100-200 credits as a pet, 30 credits as food or for its fur and tail.', 'The pet most Lemurians keep, as surface people keep cats and dogs, and the Familiar Biomancers and other mages like best. Biomancers adjusted the species to be tamer, more loyal and about as bright as a chimpanzee. Wild ones live in female-led troops of 20-40, are active by day, stay mostly on the ground, mark territory by scent and eat fruit, leaves, bark, grass and sap.', 'Rifts World Book 32: Lemuria p.50-51'),
('lemurian-aquatic-lemur', 'Lemurian Aquatic Lemur', 'animal', 'rifts', 0, 'Generally the equivalent of Scrupulous (30%), Unprincipled (50%) or Anarchist (15%), but can be any', '{"IQ":"1D6+7","ME":"1D6+5","MA":"2D6+12","PS":"1D6+2","PP":"1D6+14","PE":"2D6+8","PB":"2D6+12","Spd":"2D6+10"}', '1D6+7', '1D6+10', NULL, '2D6+7', NULL, 'I.Q. is high animal intelligence. Spd 2D6+10 is on the ground and climbing; 50% faster when running and swinging through trees; double when swimming. A.R.: not applicable.', NULL, NULL, '{"attacks":3,"initiative":3,"strike":2,"dodge":4,"roll":2}', '+2 on Perception Rolls on dry land and +4 underwater, +3 on initiative, +2 to strike, +4 to dodge and +2 to roll with impact/fall.', 'Acrobatics 80%, Climbing 75%, swim 97%, track by scent 40%, detect or find plants by smell 60%.', 'Breathes air and water alike. Nightvision 300 feet (91.4 m), sees through murky water and has good day vision. Jumps 5 feet (1.5 m) up and 8 feet (2.4 m) across and can dive 100 feet (30.5 m). Cold does half damage, and it survives as deep as 8 miles (12.8 km). A keen nose lets it follow a scent trail and sniff out plants, its hearing is exceptional, and like dogs and cats it reacts to magic and supernatural presences.', NULL, NULL, 'Body 18 inches (0.4 m) long, plus a hairless, eel-like tail of another 22 inches (0.56 m)', '4-8 lbs (1.8 to 3.6 kg)', '4-7 years in the wild; Familiars and domesticated lemurs live 2D6+14 years', 'Among Lemurians as pets and Familiars; not found in the wild', 'Lemurians, on whom they depend', 'The enemies of Lemurians', 'None; an animal. Disposition: inquisitive, playful and loyal. Value: 100-200 credits as a pet among Lemurians; 500-1,000 credits to outsiders as an exotic pet or oddity.', 'Also called the Water Lemur, Ocean Lemur or Sea Monkey. A Biomancy-engineered cousin of the Ring-Tailed Lemur with different markings, webbed hands and feet, gills behind the jaw, a short fin on the head and back, and a smooth tail like an eel''s body. All of them are domesticated and treat their Lemurian owners as pack leaders. A common pet and Familiar.', 'Rifts World Book 32: Lemuria p.51-52'),
('milu', 'Milu (Living)', 'humanoid', 'rifts', 0, 'Diabolic (45%), Miscreant (32%), Aberrant (10%) or Anarchist (10%); only living outcasts and renegades can be Unprincipled or Scrupulous', '{"IQ":"1D6+9","ME":"1D6+11","MA":"1D6+7","PS":"2D6+13","PP":"2D6+5","PE":"2D6+7","PB":"2D6","Spd":"2D6+9"}', NULL, NULL, '4D6x10+PE', '6D6', NULL, 'M.D.C. is 4D6x10 plus the P.E. attribute number, +1D6 per level of experience. P.S. is Supernatural. Spd applies to running and swimming alike. On S.D.C. worlds: Hit Points equal to P.E. x2 +1D6 per level of experience, 1D6x10+60 S.D.C. and a Natural A.R. of 17.', NULL, 11, '{"initiative":2,"strike":1}', 'Attacks per melee as per Hand to Hand: Assassin. +2 on Perception Rolls, +2 on initiative, +1 to strike, +2 to save vs psionics, possession and mind control, +6 vs Horror Factor, +4 to save vs toxins, drugs and disease, +10% to save vs coma/death. Vulnerabilities: 1. Only fair swimmers, neither fast nor proficient. 2. In sunlight, even overcast, they see only 500 feet (152 m) and are -3 on Perception Rolls, -2 on initiative, -1 on all combat rolls, lose one melee attack and are -15% on skills; dim to moderate artificial light hurts the eyes without penalty. 3. Cannot breathe air, but can stay out of water 1D4+6 hours at a time.', 'Milu R.C.C. (70% of the living population): Appraise Goods (+30%), Barter (+10%), Begging (+15%), Climbing (+15%), Dance (+20%), Dowsing (+10%), Fasting (+15%), Gambling (+10%), Hand to Hand: Assassin, Sing (+20%), Imitate Voices & Sounds (+20%), Language (Native; roughly the same as the Ichthylean and Junk Crab tongue) at 95%, Palming (+20%), Pick Locks (+15%), Pick Pockets (+10%), Prowl (+20%), Tailing (+10%), Tracking (people; +20%), Underwater Navigation (+10%), Underwater & Sea Survival (+10%), W.P. Knife or Blunt (pick one), W.P. Energy Pistol, W.P. 1D4 of choice (any). Identify and track the smell of dead flesh, blood and decay: 60% +3% per level of experience.', 'Nightvision 3,000 feet (914 m), sees underwater, tolerates depths of 12 miles (19.2 km) and takes half damage from cold. Supernatural Strength and Endurance. Hearing is about human, but two head antennae taste the water and pick up dead flesh, blood and rot from three miles (4.8 km) off. The feelers also read the planet''s magnetic field for underwater navigation, show the electrical outline of any living creature within 50 feet (15 m) regardless of darkness, murk, plant cover or magical invisibility, and feel movement 200 feet (61 m) away in water, a third of that in air. Milu talk by touching antennae, or with chirps, creaks and bubbling over distance.', 'Only via the Necromancer O.C.C. (see Rifts Africa, page 99, or Rifts Mystic Russia, page 83).', 'None.', '7-8 feet (2.1 to 2.4 m) tall; 9-12 feet (2.7 to 3.6 m) wide when legs are fully extended. Females are typically 20% larger.', '600-1,200 lbs (270 to 540 kg)', '90-130 years for the living Milu', 'Lone prowlers, pairs and groups of 1D4+2 can turn up anywhere, as can any number of zombies (5D6 is typical). The stronghold is Davey Jones''s Locker and the City of Bones in the depths of the Indian Ocean, along the African coast and around Madagascar, plus that ocean''s many Dead Pools.', 'Only their own kind; any pact with other evil beings lasts only while it serves the Milu. Davey Jones is their Master Vampire, demigod and General of the Army on Earth.', 'Lemurians first of all, then the Lemurians'' allies, the Minions of Splugorth and vampire hunters. The Naut''Yll, the Lord of the Deep, the Vampire Kingdoms and the Splugorth are rival conquerors; the New Navy and Tritonia have also fought them. All sentient life is food, plaything and enemy.', 'NPC villain. 30% of the Milu are Necromancers, the only O.C.C. open to them; the other 70% of the living use the Milu R.C.C. skills. A third of the whole population is the undead Mahiki Milu. Disposition: aggressive, cold-blooded cutthroats who see non-Milu as food, slaves and raw material for undead; fatalistic, and ready to sacrifice friends or kin to keep their own position.', 'A crab-like people from the ocean world Ka-pa''a-he''o: one big crab claw, one humanlike arm and four crab legs in a bony shell. Once carrion scavengers, they took up an alien Necromancy and the worship of a Vampire Intelligence, The Dark Warmth of Cold Death, overran their world and reached Rifts Earth during the Great Cataclysm. The living are death cultists (70%) or Necromancers who obey their god and the vampire aristocracy, and count it an honor to be chosen for undeath. Sunlight blinds them, so they surface only at night. Young hatch from communally laid eggs and start work at about 10% of adult size.', 'Rifts World Book 32: Lemuria p.155-157'),
('mahiki-milu', 'Mahiki Milu (Milu Vampire)', 'undead', 'rifts', 0, 'Diabolic (45%), Miscreant (35%), Aberrant (13%) or Anarchist (7%)', '{"IQ":"1D6+13","ME":"1D6+13","MA":"1D6+13","PS":"3D6+30","PP":"2D6+7","PE":"2D6+13","PB":"2D6","Spd":"2D6+13"}', NULL, NULL, '4D6x10+66', NULL, NULL, 'M.D.C. is 4D6x10+66, +2D6 per level of experience. P.S. is Supernatural. Spd applies to running and swimming alike. On S.D.C. worlds: Hit Points equal to P.E. x3 +2D6 per level of experience, 1D6x10+60 S.D.C., harmed only by wood, silver and sunlight, with magic doing half damage. Horror Factor 11 and P.P.E. 6D6 are not reprinted for the vampire; they are the living Milu''s figures, which the entry says carry over.', NULL, NULL, NULL, 'The entry prints no Horror Factor, P.P.E., attacks or bonuses for the vampire; it says only that it keeps the basic stats of the Milu. The living Milu block gives Horror Factor 11, P.P.E. 6D6 and these bonuses: Attacks per melee as per Hand to Hand: Assassin. +2 on Perception Rolls, +2 on initiative, +1 to strike, +2 to save vs psionics, possession and mind control, +6 vs Horror Factor, +4 to save vs toxins, drugs and disease, +10% to save vs coma/death. Vulnerabilities: silver, wood, sunlight and holy symbols as usual for vampires, but running water does nothing, Holy Water does half damage and most magic spells and weapons do half. Life-radiant Bio-Energy does double damage. Wood, even S.D.C. wood, does its damage point for point as M.D. Sunlight and sunlight-based attacks do double the usual damage as M.D. and blind them (-10 to all combat rolls); Globe of Daylight does 4D6 M.D. per melee round, dimly sunlit water 4D6 M.D. per melee round and sunlight 1D6x10 M.D. per melee round (the Milu overview on p.155 says sunlit water does 5D6 M.D. per melee round). No Bio-Regeneration in daylight. Soil of the homeland: not applicable.', 'The R.C.C. skills of the Milu. Prowl underwater 50% +2% per level of experience; -20% on dry land and impossible in sunlight. Blood scent is double the living Milu''s range.', 'An aquatic Secondary Vampire with the Milu''s M.D.C. and the usual powers except as follows. Undead and immortal: no need for air or food, no body heat, no disease, and most mortal weapons do nothing. Vampire mind control, enslavement and blood hunger are standard. Its Slow Kill Bite makes new vampires, almost always from Milu. Summons sharks or barracudas in place of wolves, and ordinary crabs in place of land vermin. Metamorphosis is limited to a red-eyed black or dark gray manta ray or large shark; no mist and no surface animals. Animates and commands 1D4x10 dead as the Animate and Control Dead spell. Lives on the surface or underwater indefinitely if kept from the sun. Path Walkers (non-Milu victims turned by a Mahiki): as smart as a Secondary Vampire, always subservient, share these powers and weaknesses but cannot change shape, summon animals or make vampires; they animate 1D4 dead and their Slow Kill Bite makes one Zombie Servant a week. Zombie Servant: I.Q., M.E., M.A., P.B. and Spd halved, P.P. cut by a third, P.S. and P.E. +2D6 and Supernatural, Hit Points plus S.D.C. become M.D.C., keeps 1D6+3 skills that never improve, and has the Mahiki''s vulnerabilities.', 'Animate and Control Dead as a vampire power (1D4x10 dead). Otherwise only via the Necromancer O.C.C.', 'Standard as per vampires.', 'As the living Milu: 7-8 feet (2.1 to 2.4 m) tall; 9-12 feet (2.7 to 3.6 m) wide when legs are fully extended', 'As the living Milu: 600-1,200 lbs (270 to 540 kg)', 'Immortal (undead)', 'As the living Milu: the City of Bones and Davey Jones''s Locker in the depths of the Indian Ocean, the African coast, the waters around Madagascar and the Dead Pools', 'The living Milu, Davey Jones, and their Path Walker and Zombie Servant minions', 'Lemurians and Biomancers above all, whose Bio-Energy does them double damage; otherwise as the living Milu', 'NPC villain; roughly a third (33%) of the Milu population. They are the aristocracy, rulers and warrior elite. They seldom feed on fellow Milu, preying on conquered and enslaved peoples instead. Their Vampire Intelligence, The Dark Warmth of Cold Death, dwells in another dimension rather than on Earth; Davey Jones is its link, and without him no new undead can be made.', 'A Milu crab person turned by another Mahiki, usually at their god''s direction, into the equivalent of a Secondary Vampire. It keeps the living Milu''s basic stats with higher attributes and M.D.C. and adds sea-flavored vampire powers. Non-Milu it turns become lesser vampires called Path Walkers (short for those who "Walk the Path of the Mahiki"), who in turn make mindless, obedient Zombie Servants used as labor, guards and cannon fodder. Sunlight destroys all three kinds.', 'Rifts World Book 32: Lemuria p.157-158'),
('blue-otter', 'Blue Otter', 'animal', 'rifts', 0, 'Unprincipled (80%), Scrupulous (10%) or Anarchist (10%)', '{"IQ":"1D6+8","ME":"2D6+8","MA":"2D6+9","PS":"1D4+6","PP":"2D6+10","PE":"2D6+7","PB":"2D6+7","Spd":"2D6+7"}', 'PE+1D6', '2D6', NULL, 'PEx4+1D6', 'MEx2+1D4', 'I.Q. is high animal intelligence. Spd is doubled in water. Hit Points are P.E. plus 1D6 per level of experience. P.P.E. is P.E. x4 plus 1D6 per level of experience or per four years of age (G.M.''s choice). I.S.P. is M.E. x2 plus 1D4 per level. Hit Points and S.D.C. become M.D.C. on a ley line or inside a ley line triangle such as the Bermuda Triangle. Experience level is typically 1D4, or as the G.M. wishes up to 9th, never higher. Horror Factor: not applicable.', NULL, NULL, '{"attacks":3,"initiative":3,"strike":2,"dodge":4,"pull":4}', '+3 on Perception Rolls. The +4 dodge is an automatic dodge that uses no melee attack. All combat bonuses are halved on dry land, rounding down. Bonuses are in addition to any attribute bonuses. Vulnerabilities: none as such, though curiosity and trust in humans get them captured or killed.', 'Equivalent skills: Swimming 98%, Climbing 50%, Prowl 60%, Detect Concealment 30%, Detect Ambush 40% and Escape Artist 35%; each rises 3% per level of experience.', 'Holds its breath 3D4+10 minutes, nightvision 120 feet (36.6 m), swims and tolerates depths to 600 feet (183 m). Cold does nothing to it, and magic cold or magic ice weapons do half damage. Heightened Sense of Smell: track by scent 40% +2% per level, identify foods 60% +3% per level. Heightened Sense of Touch: whiskers feel motion in water and air, so fighting blind or against an invisible foe costs only -5 on strike, parry and dodge rolls. Ley Line M.D.C.: both its S.D.C. and its Hit Points turn into M.D.C. automatically, at no P.P.E. cost, on a ley line or in a ley line triangle; its bite stays S.D.C. Ley Line Speed Doubler: swims at twice normal speed without tiring along a ley line, in water only. Sense Ley Line: as the Ley Line Walker O.C.C. ability.', 'Casts at level one: Armor of Ithan (10), Cleanse (6), Float in Air (5), Sense Evil (2) and Sense Direction Underwater (4). Learns ONE new spell per additional level of experience, chosen from Ocean Magic and/or Spell Invocations levels 1-3; they favor defensive and helpful spells over combat ones.', 'Bio-Regeneration (self; 6), Empathy (4), See the Invisible (4), Sense Magic (3), Sense Time (2), Sixth Sense (2) and Stop Bleeding (4). One more Sensitive power per new level of experience (seldom past level 4).', '4-6 feet (1.2 to 1.8 m) long', '80-120 lbs (36 to 54 kg)', '3D6+12 years', 'Rocky sea coast. Prefers cool climates but survives in any temperature range.', 'Lemurians, humans and humanoid D-Bees; most of all easy-going, playful practitioners of magic, Mystics and Amphibs', 'Those who hunt them (sea monsters, sharks, Horune Pirates), cruel and wicked people, and supernatural evil including the Lord of the Deep, his undead legions and the Minions of Splugorth', 'No O.C.C.; an animal, kept as a pet, companion or Familiar. Value: about 15,000 credits as a pet or zoo animal, up to 10,000 credits for one pelt, and upward of 40,000 credits from a buyer who wants a Familiar. An owner can seldom direct its magic, which is instinct.', 'A clever, agile, playful otter from another world, also called the Mystic Otter or Blue. It seeks out people, especially humans, Lemurians and Amphibs, plays with swimmers, aids sailors in trouble and is easily tamed when young, growing smarter than a dog and fiercely loyal. What sets it apart is inborn magic and psionics much like a Mystic''s, which makes it a prized Familiar for Lemurians, Ocean Wizards, Sea Druids and mainland mages.', 'Rifts World Book 32: Lemuria p.167-168'),
('death-hunter-fish', 'Death Hunter Fish', 'monster', 'rifts', 0, 'Anarchist', '{"IQ":"1D4+2","ME":"1D4+2","MA":"1D4+2","PS":"1D6+6","PP":"2D6+2","PE":"2D6","PB":"1D4","Spd":"3D6+10"}', '3D6+8', '1D6x10', NULL, '2D6+10', NULL, 'Animal intelligence. Spd is swimming speed. Natural A.R. 9. Can temporarily become a Mega-Damage creature: see Bio-Energy Field under natural abilities. Horror Factor is 10 for most beings but 12 for the undead.', 9, 10, '{"attacks":2,"strike":4,"dodge":3}', '+2 on Perception Rolls and +4 on initiative against the undead only. Bonuses are in addition to any attribute bonuses. Vulnerabilities: none as such. Attacks alone, in pairs, trios or groups of 5-10, and may hunt in schools of up to 120.', 'Equivalent skills: Swimming 98%, Prowl 80% and Underwater Navigation 90%.', 'Good underwater vision, nightvision 2,000 feet (610 m), depth tolerance 7 miles (11 km). Attacks in groups of 1D6+4; schools number 3D4x10. Bio-Energy Field M.D.C. Transformation: when it attacks undead it spends its P.P.E. to convert its Hit Points, but not its S.D.C., into M.D.C. one for one, and its bite does double damage to them. Each undead a school kills gives every fish within 90 feet (27.4 m) 1D4+6 M.D.C., added or restored. The change holds while any undead is within a mile (1.6 km). Chemoreceptors: 86% to track undead and dead or decaying flesh, 68% to track blood or identify chemicals, toxins and creatures by scent, five mile (8 km) radius. Sense Undead: 95% to locate undead by necromantic energy, two miles (3 km). Eat Undead: undead it devours cannot regenerate and are destroyed for good. An undead that bites it or drinks its blood takes 4D6 Hit Points/M.D. per bite, and 4D6 per melee spent in its seeping blood. A weapon coated in the blood does +1D6+3 damage to vampires and other undead until 10 minutes after it dries; splashed blood works as Holy Water.', 'None', 'None', '2 to 5.5 feet (0.6 to 1.7 m) long and up to 1 foot (0.3 m) wide', '36 to 103 lbs (16 to 46 kg)', '2D6+6 years', 'Schools gather and hunt around Dead Pools, recently sunken ships, underwater battlefields, Milu strongholds and anywhere the undead dominate; may also turn up unexpectedly to scavenge a carcass.', 'Leaves the living alone, and most predatory fish and sea monsters leave it alone. Lemurians commune with them to send them against undead and to guard permanent underwater outposts. Lemurians, Merans and Ichthyleans count one or two small schools as good luck; several or large schools (3D4x10 fish) mean undead or a place of death nearby.', 'Undead of all kinds, the Milu above all; also beings allied to or empowered by gods of death, Bonelings, Naga Deevils, Death Demons, Ghouls, Nasu, Soul Catcher demons, Necromancers, and Witches, mages and monsters who use Necromancy, Soulmancy or Demon Magic', 'No O.C.C.; an animal. Value: Lemurians, some aquatic D-Bees and Undead Hunters work a single fish or a small pack to find undead. One trained fish brings up to 1D6x10,000 credits and a school of four up to 4D6x10,000. Mortals can eat the meat safely, though it is fatty and foul.', 'A slim, silver-tinted fish something like a barracuda, known to Polynesians as Keoni I''a, the Righteous (Hunter) Fish. Its jaws unhinge like a snake''s to tear at carrion, but what it likes best is hunting the undead, which it finds by smell and by a supernatural feel for necromantic energy. It ignores the living unless cornered, except those who carry the taint of death magic such as Necromancers. An autopsy found unusual amounts of silver in its body.', 'Rifts World Book 32: Lemuria p.168-170'),
('giant-sea-slug', 'Giant Sea Slug', 'monster', 'rifts', 0, 'Anarchist or Miscreant', '{"IQ":"1D4","ME":"1D4","MA":"1D4","PS":"2D6+40","PP":"1D6+5","PE":"1D6+28","PB":"2D6","Spd":"1D6+2"}', NULL, NULL, '1D6x100', '2D6', NULL, 'Low animal intelligence. P.S. is printed 40+2D6 and is Robotic. Spd 1D6+2 is swimming; crawling Spd is 2D4+4. On an S.D.C. world: 3D6x10 Hit Points, 4D6x10 S.D.C. and Natural A.R. 9. Small ones, such as Familiars, have one third the Hit Points and S.D.C. of a mature wild slug.', NULL, 10, '{"attacks":2}', '+1 to strike with its bite. Senses invisible foes and fights by hearing alone, with no penalty for blindness. Bonuses are in addition to any attribute bonuses. Vulnerabilities: Blind (no eyes or optical sense of any kind). Breathing Tentacles: the 2D6x10 tendrils on its back are its gills, each with 1D6+1 M.D.C., and losing all of them suffocates it. Slow and Ponderous: poor maneuverability.', 'Equivalent skills: Swimming 50%; it prefers to crawl along the bottom.', 'Unharmed by toxins, oil, fossil fuel, chemical poisons, spoiled food and cold; heat does half damage and magic cold one third. Depth tolerance 6 miles (9.6 km). Chemoreceptors: tastes toxins, toxic chemicals and waste from as far as ten miles (16 km); Track by Scent 80%; recognizes other chemicals, toxins, blood and salinity at 60%. Heightened Sense of Hearing: locates moving objects in water at 90%, hears into the ultrasonic range and is drawn toward mechanical noise.', 'None', 'None', 'Most are 16-24 feet (4.8 to 7.3 m) long; the largest reach 60 feet (18.3 m) long and 20 feet (6.1 m) tall and wide', '3-5 tons on average, 15-20 tons for the largest', '2D6+40 years', 'Dead Pools, toxic waste dumps and the sites of toxic spills', 'None but its own kind; Lemurians sometimes keep small ones as pets or Familiars', 'Almost none. Large animals, sea monsters and other monsters sometimes eat it, as do the Milu undead around the Dead Pools of the Indian Ocean.', 'No O.C.C.; an animal. Value: none. A young slug kept on a small, steady diet stays between grapefruit and watermelon size and can serve as a pet or Familiar.', 'A Lemurian-made cross of sea slug and anemone, bred to eat the ocean''s garbage, and also called the Living Garbage Disposal, the Devourer or the Rainbow Slug. It digests rot, oil, fuel and toxic waste, and on that diet swells from the size of a small egg to the size of a house, its hide as many-colored as what it eats. With no waste to hand it eats reefs, plants, wood, carrion and the sick or injured. When it dies, its decay neutralizes the toxins it carried and leaves fertile remains.', 'Rifts World Book 32: Lemuria p.170-171'),
('ichthyosaur', 'Ichthyosaur', 'monster', 'rifts', 0, 'Unprincipled or Anarchist', '{"IQ":"1D6+6","ME":"1D6+6","MA":"2D6+3","PS":"4D6+6","PP":"2D6+10","PE":"2D6+11","PB":"1D6+6","Spd":"3D6+45"}', NULL, NULL, '1D6x10+15', '4D6', NULL, 'P.S. is Robotic. Spd is swimming, on average 32-38 mph (51.2 to 60.8 km). M.D.C. 1D6x10+15 is a juvenile''s; add 1D4x10+20 M.D.C. per 100 years of age. P.P.E. is 4D6 to start, +1D6 per 100 years. On an S.D.C. world: 5D6+10 Hit Points, 1D6x10 S.D.C. and Natural A.R. 12, plus 5D6 Hit Points and 1D6x10 S.D.C. per 100 years of life. Horror Factor is 10 for juveniles and 12 for adults.', NULL, 10, '{"attacks":3,"initiative":2,"strike":3,"dodge":2,"pull":2,"roll":2}', '+3 on Perception Rolls. Bonuses are in addition to any attribute bonuses, and both bonuses and damage are doubled for ancient Ichthyosaurs 500-600 years old. Vulnerabilities: breathes air and holds its breath 1D4x10+20 minutes; out of water its skin dries and it dies of dehydration after 1D4+1 hours.', 'Equivalent skills: Swimming 98%, Prowl 60%, Underwater Navigation 98%, Track and Hunt Sea Animals 90%.', 'Scaly hide, nightvision 200 feet (61 m), depth tolerance 2 miles (3.2 km), half damage from cold. Hears prey to 3,000 feet (914 m) and locates moving objects in water at 90%. Senses electromagnetic energy to 3,000 feet (914 m), so it has no blindness penalty against living things. Sense Magnetic North: as a dolphin; a hard blow to the head stops it for 3D4 minutes. M.R.I. Probe: as the dolphin''s Ultrasonic Probe; base skill 65% at 100 feet (30.5 m) or less, -20% out to 200 feet (61 m), and -40% skill and range against large or heavily armored ships. Reads wall thickness, weak spots, heat sources, engine rooms and crew positions, and in the living finds pregnancy, tumors, foreign objects, bionics and implants, and identifies species, magic or supernatural beings and disguised shape-changers (not magical metamorphosis). Dolphin maneuvers: Dive at double speed to 500 feet (152 m) +100 feet (30.5 m) per level. Mid-Air Leap: a juvenile clears 7 feet (2.1 m) and an adult 14 feet (4.2 m); a Precision Leap to grab or knock away an item is +2 to strike and costs three melee actions. Quick Turns & Stops succeed on 14 or better. Speed Burst: double speed for one minute, six times an hour, +2 to dodge or strike. Breaching/Skimming: 20% less top speed and no speed bursts. Tight Circle: 12 feet (3.6 m) across.', 'None', 'None', 'Juveniles 9-15 feet (2.7 to 4.6 m) long; adults (over 100 years) 20-30 feet (6.1 to 9.1 m); ancient (over 400 years) 35-40 feet (10.6 to 12.2 m)', 'Juveniles 600-2,000 lbs (270 to 900 kg); adults 5-10 tons', '600 years (roll 1D6 for random determination); juvenile for the first 100 years', 'Oceans worldwide, wherever dolphins and whales are found', 'Other Ichthyosaurs, dolphins and whales. Lemurians, Ichthyleans, Merans, Naut''yll and other aquatic peoples keep them as pets, watchdogs, mounts and attack animals.', 'Large marine predators, sea serpents and sea monsters', 'No O.C.C.; an animal. Value: a tamed, trained one sells for 20,000-40,000 credits as a pet, companion or mount, and to animal shows and arenas. The M.D.C. hide makes light body armor of 32 M.D.C. weighing 10 lbs (4.5 kg) with no movement penalty.', 'A prehistoric marine reptile that looks like a dolphin crossed with a crocodile, known as Mo''o I''a (Lizard Fish), Dolphin Lizard or Ichthy. Wild ones hunt tuna, marlin, mammals and humanoids in packs of 2D4+1 and use traps and tactics, though they are less bright than dolphins and often swim with and defend dolphins and whales. Raised from young by aquatic humanoids they are tame, loyal and friendly, and serve as mounts, guards and attack animals.', 'Rifts World Book 32: Lemuria p.171-173'),
('jonahs-fish', 'Jonah''s Fish', 'monster', 'rifts', 0, 'Unprincipled (70%) or Anarchist (30%)', '{"IQ":"1D4+2","ME":"1D6+6","MA":"1D6+4","PS":"2D4+40","PP":"1D6+6","PE":"2D6+10","PB":"1D6","Spd":"1D4x10+40"}', NULL, NULL, '1D4x100+600', '5D6', NULL, 'Low animal intelligence. P.S. and P.E. are Supernatural. Spd is swimming, 35-55 mph (56 to 88 km). On an S.D.C. world: 2D6x100 Hit Points, 4D6x100 S.D.C. and A.R. 16.', NULL, 9, '{"attacks":2,"dodge":1}', 'The +1 to dodge applies underwater, in addition to any attribute bonuses. Not aggressive: it attacks people and ships only when threatened or when a Lemurian commands it. Vulnerabilities: neither smart nor maneuverable, it relies on its armor.', 'Equivalent skills: Swimming 98% and Prowl 70%.', 'Fast swimmer with tough scales, nightvision 1,000 feet (305 m), half damage from cold including magic cold, and depth tolerance of 8 miles (12.8 km), though passengers are held to their own limit. Its thermal reading is low, and those inside escape most sensors until they leave by the mouth. Air Bladders: each of the two buoyancy bladders holds 1D6+4 human-sized passengers and still works, for three days at most; stale air leaves through the gills and fresh oxygen is stored. Every three days it surfaces and empties the bladders, riders included. The mouth and a double muscle flap form an airlock, so riders can leave underwater without loss of pressure or buoyancy. Lemurians steer it by psionic Empathy and Telepathy, and it is docile and compliant. Cloaking: its own biological signature hides whatever is inside, even strong magic energy; it swims quietly (Prowl 70%), gives off no heat and is usually taken for a dumb animal.', 'None', 'None', '100 to 120 feet (30.5 to 36.6 m) long, 30-40 feet (9.1 to 12.2 m) wide and 25-30 feet (7.6 to 9.1 m) high, full grown', '60-70 tons', '2D6+50 years', 'Oceans worldwide, from the deep sea to shallow waters and coral reefs', 'Its own kind and Lemurians, who alone ride inside the air bladders, also use it to haul heavy cargo, and so feed and protect it. Some aquatic D-Bees and humans ride on its back. Usually met alone, in pairs or in fours; a large school is 8-12.', 'Sea monsters, sea serpents, Splugorth Metztla and similar giants eat it. Some seafaring and aquatic peoples, Horune Pirates among them, hunt it like a whale for meat, oil, hide, bones and teeth.', 'No O.C.C.; an animal. Value: 50,000 to 75,000 credits for a tamed one among Lemurians, as a living submarine, transport or cargo hauler. Primitive peoples (not Lemurians) turn the hide into heavy body armor of 140 M.D.C. (-15% movement penalty, and running and swimming speed down 10%), boats and rafts of 100-200 M.D.C. and huts of 50-200 M.D.C., and make spearheads, knives, short swords and war clubs from bone and teeth that do 1D4, 1D6 and 2D4 M.D.', 'A fat, ugly fish as big as a large house, also called the Carrier, Transport or Armored Fish. Lemurian warriors climb through two muscle flaps in its mouth into the air bladders that keep it afloat, and ride unseen and unheard behind enemy lines or to surface shores. It also serves as a living tank, ramming ships and swallowing prisoners and valuables from the water; some riders lash themselves to the outside instead. For all its huge mouth and teeth the size of daggers and short swords it lives on small fish, shrimp, plankton and krill, swallowed whole.', 'Rifts World Book 32: Lemuria p.173-174'),
('kilmorans-eel', 'Kilmoran''s Eel', 'monster', 'rifts', 0, 'Anarchist (tamed) or Miscreant (wild)', '{"IQ":"1D4+5","ME":"2D6+3","MA":"2D4","PS":"2D4+29","PP":"2D6+12","PE":"2D6+8","PB":"1D6+4","Spd":"2D6+60"}', NULL, NULL, '3D6x10+20', '6D6', NULL, 'High animal intelligence. P.S. and P.E. are Supernatural. Spd is swimming, 42-48 mph (67 to 77 km, 36 to 41 knots); crawling on land it moves at 28 mph (45 km). On an S.D.C. world: 1D6x10+20 Hit Points, 2D4x10+20 S.D.C. and Natural A.R. 12.', NULL, 13, '{"attacks":4,"initiative":3,"strike":2,"dodge":5,"pull":4,"roll":2}', '+3 on Perception Rolls and +6 M.D. to bite damage. The +5 dodge is an automatic dodge that uses no melee attack; pull is for punch or bite. Bonuses are in addition to any attribute bonuses. Vulnerabilities: dehydration on dry land; wild ones can be over-aggressive and may fight to the death; fire and heat attacks do 50% more damage, and fire has a Horror Factor of 11 for them.', 'Equivalent skills: Climbing 30%, Detect Ambush 80%, Detect Concealment 40%, Escape Artist 45%, Prowl 80%, Swimming 98%, Track and Trap Undersea Animals 80%, Underwater Navigation 98%, and Land Navigation (surface and underwater) 95%.', 'Tough skin, nightvision 2,000 feet (610 m), half damage from cold, depth tolerance 6 miles (9.6 km); hears prey to 3,000 feet (914 m) and locates moving objects in water at 90%. Amphibious Nature: breathes and travels on dry land 1D4+1 hours, 1D6+28 hours in swamp or damp, two hours in desert or frozen waste. Past that it dehydrates and dies within 1D4 hours, with M.D.C., attacks and combat bonuses halved each hour; back in the sea it recovers fully in 4D6+24 hours. Automatic Dodge. Photographic Memory and Land Navigation: remembers every place and face, and grasps three-dimensional structure well enough to guess where a tunnel leads or how thick a wall is. Quick Turns & Stops succeed on 12 or better; a failure overshoots or collides. Speed Burst: double speed for one minute, six times an hour, +1 to dodge or +2 to strike. Tight Circle/Turn: 15 feet (4.6 m) across.', 'None', 'None', '30-50 feet (9.1 to 15.2 m) long and 3-5 feet (0.9 to 1.5 m) in diameter', '1,000-3,000 pounds (450 to 1,350 kg)', '300-500 years', 'Tropical and warm oceans, underwater mountains and coastal waters by preference, but anywhere outside the arctic, and wherever Lemurians keep them as guards and mounts', 'Tolerates its own kind but hunts and travels alone or in pairs, never in schools. Dislikes most humanoids; Lemurians have bonded with them, and now and then another aquatic race tames and rides one.', 'Large marine predators, sea monsters, sea serpents and Metztla. Wild ones treat humanoids as easy prey and have capsized or sunk canoes and small boats to reach those aboard. Eats fish of any size, otters, dolphins, seals, walrus and like animals up to 10 feet (3 m) long.', 'No O.C.C.; an animal. Value: a trained mount or guardian brings 10,000-20,000 credits among Lemurians and two or three times that elsewhere. A wild, untamed one sells to zoos and gladiatorial arenas for 1D4x10,000 credits.', 'A giant eel, Moana Makani Puhi (the Wind Sea Eel) to Polynesians, also called the Giant Eel or Giant Cave Eel. Quick in open water, it is at its deadliest in mazes, wrecks, tunnels and canyons, darting through gaps like a snake in a burrow. It is named for Eric Kilmoran, the handler who supplied them to undersea arenas in the South Pacific as maze monsters. It can slither over dry ground quickly and rear up on its tail to carry a Lemurian rider into a short land fight, and Serpent Hunters prize it as a mount for tight places.', 'Rifts World Book 32: Lemuria p.174-176'),
('line-ray', 'Line Ray', 'monster', 'rifts', 0, 'Unprincipled (65%) or Scrupulous (35%)', '{"IQ":"1D6+7","ME":"2D4+10","MA":"2D6+9","PS":"2D6+13","PP":"2D4+15","PE":"2D6+15","PB":"2D6+10","Spd":"3D6+21"}', NULL, NULL, 'PEx10', '3D4x10+PE', 'ME+2D6', 'High animal intelligence. P.S. and P.E. are Supernatural. Spd is 15-23 mph (24 to 36.8 km, 13-20 knots) swimming underwater, doubled along ley lines, or in the air. On S.D.C. worlds: 2D4x10 plus P.E. Hit Points, 4D6x10 S.D.C. and A.R. 8. I.S.P. and psionic abilities do not increase over time. Horror Factor/Awe Factor is 11, but 13 against the enemies of Lemuria.', NULL, 11, '{"attacks":3,"initiative":2,"dodge":2}', '+2 on Perception Rolls (+4 where a ley line is concerned, such as an approaching Ley Line Storm) and +1 on all saving throws. Bonuses are in addition to any attribute bonuses. Vulnerabilities: most of its special powers depend on ley lines; also its size and its association with Lemurians.', 'Equivalent skills: Swimming 98%, Prowl 65%, Underwater Navigation 95% and Land Navigation 80%.', 'Nightvision 1,000 feet (305 m); hears prey to 3,000 feet (914 m) and locates moving objects in water at 90%; feels movement in the water within 60 feet (18.3 m); 10 mile (16 km) depth tolerance; heals twice as fast as a human. Limited Amphibious Nature: breathes air one minute per P.E. point and survives out of water P.E. x2 minutes (x5 on a ley line); it cannot move on land. After that it dies within 1D4 hours, with M.D.C., P.P.E., I.S.P., attacks and bonuses halved each hour; returned to the sea it is well again after 3D6+12 hours. Ley Line Storms cannot hurt it: it rides one at triple flying speed and is never struck. Ley Line Energy Blast: on a ley line only, one melee action, range 1,000 feet (305 m) +400 feet (122 m) per level, up to 2D6 S.D.C. or M.D. in 1D6 steps, costing one P.P.E. for S.D.C. or five for M.D.C. Ley Line Flight: like Ley Line Drifting, swimming at double speed or flying at swimming speed up to 1,000 feet (305 m) high, ending when it leaves the line. Ley Line Healing: 2D6 M.D. an hour on a line; regrows a tail in 1D6 days, part of a wing in 1D6+6 and a whole wing within 3D6+12. Ley Line Hopping: at top speed, after 1D4 melee rounds of focus and 10 P.P.E., it Rifts itself and up to two riders to a neighboring line, or along the same one; reach is three miles (4.8 km) for young rays, six (9.6 km) for adults and ten (16 km) for those over 100 years old.', 'Ley Line Walker equivalent abilities: Sense Ley Lines and Magical Energy, Read Ley Lines, and Ley Line Phasing (passengers included). Spells: Chameleon (6), Cleanse (6), Globe of Daylight (2), Ley Line Fade (20), Invisibility: Simple (6), Negate Poison/Toxin (5), See Aura (6), See the Invisible (5) and Sense Evil (2). Gains no new spells over time.', 'Resist Fatigue (4), Resist Hunger (2), Sense Dimensional Anomaly (4) and Sense Time (2). I.S.P. is M.E. +2D6; neither I.S.P. nor abilities increase over time.', '18-25 feet (5.4 to 7.6 m) long from face to rump, plus 8-10 feet (2.4 to 3 m) of twin tails; wingspan 30-40 feet (9.1 to 12.2 m)', '3-5 tons', '120-200 years in the wild, double in the care of Lemurians', 'Oceans around the globe, preferring tropical and temperate areas. Met alone, in pairs, trios and small schools of 2D6+4, often in the company of Mega-Rays, dolphins and whales.', 'Other Line Rays, Mega-Rays, dolphins, whales, Lemurians, Merans, Ichthyleans and Sea Druids (those of the Manta Ray totem especially); will accept taming by other peaceful, nature-loving and mostly aquatic peoples. The favored mount of some Serpent Hunters and many Oceanic Guardsmen, Wilderness Scouts, Biomancer Gene-Mages and other aquatic mages.', 'Supernatural evil and the undead; demons, the Milu, the Lord of the Deep, and the Splugorth and their minions', 'No O.C.C.; an animal. Value: no price is printed. It serves Lemurians gladly as a mount, but one enslaved or forced to work has a 01-75% chance to stop eating and die within 2D4 weeks, unless it manages to escape.', 'A manta ray three to four times normal size, aqua-green above and cream below, with twin tails; thought to be a Lemurian Biomancer creation meant as a smart, graceful mount. Also called Makani Hahalua (Wind Manta Ray), Keheu Hahalua, Ley Line Ray or Flying Ray. Like a Mystic it has inborn magic and psionics, and along a ley line it can leave the sea and fly, which suits it to rescues, scouting and surprise raids. It is calm under pressure and deeply loyal to its rider.', 'Rifts World Book 32: Lemuria p.176-177'),
('mega-ray', 'Mega-Ray', 'monster', 'rifts', 0, 'Considered Unscrupulous or Anarchist', '{"IQ":"1D6+3","ME":"2D6+2","MA":"2D6","PS":"2D4+24","PP":"1D6+11","PE":"1D6+16","PB":"1D6+11","Spd":"2D6+33"}', NULL, NULL, '2D4x10+57', '1D4x10+8', 'MEx3', 'I.Q. is high animal intelligence. P.S. is equal to Robot Strength. Spd is swimming (on average 30 mph/48 km or 26 knots). On S.D.C. worlds: 1D4x10 + P.E. attribute number Hit Points, 2D6x10 S.D.C. and A.R. 8.', NULL, 12, '{"attacks":2,"dodge":2}', '+2 on Perception Rolls, +2 to dodge and +3 to save vs possession/mind control, in addition to possible attribute bonuses. Horror Factor 12 applies only when it appears suddenly or attacks aggressively; seen from afar it looks slow, graceful and unthreatening. A full speed ram counts as two melee attacks.', 'Equivalent skills: Swim 98%, Fishing 88%, Prowl 55% and Land Navigation 70%.', 'Nightvision 1,000 feet (305 m). Keen hearing finds anything moving in the water at 80% and picks up prey as far off as 3,000 feet (914 m). Ordinary cold does nothing to it and magical cold does half damage. Depth tolerance 5 miles (8 km). Sonar Stealth (special): its thin profile reflects sound badly, so sonar detection is at -30%; it also swims with silent wing strokes and no engine, so anyone listening for one with superior hearing or listening gear is at -35% on the skill or ability and -2 on Perception Rolls.', 'None.', 'Bio-Regenerate (self; 6), Empathy (4), Increased Healing (10), Presence Sense (4) and See the Invisible (4). Base I.S.P.: M.E. attribute number x3.', '25-40 feet (7.6 to 12.2 m) long from the front of the face to the rump; the twin tails add another 10-12 feet (3 to 3.6 m); wingspan 40-70 feet (12.2 to 21.3 m)', '5-8 tons', '25-30 years in the wild, 50% greater when cared for by Lemurians', 'Open water, following krill and plankton over coral reefs and around seamounts. Thickest around Lemurian cities and outposts, with small numbers in oceans worldwide; tends to avoid the colder polar seas.', 'Lemurians, Merans and Ichthyleans. A wild ray reads people with Empathy and may trust anyone who means it no harm, even letting divers ride it briefly.', 'The Milu, the Lord of the Deep and the Splugorth, who enslave the rays for underwater arenas, labor and Bio-Wizard experiments', 'No O.C.C.; a tamed work and riding animal. Also known as Giant Ray, Sea Kite and Lemurian Manta Ray. Value: 75,000 to 150,000 credits to outsiders as a trained mount, and one quarter of that inside Lemuria. Slow to breed: the female carries her eggs for up to a year and bears live young, two on average.', 'A giant manta ray reshaped by Biomancy into a natural Mega-Damage animal, green above and dark below, with two long tails added so outsiders confuse it with the Line Ray. Lemurians keep them as everyday work and riding beasts, often under saddles that carry weapons, and let them graze free on krill and plankton until called by psionics. Wild ones are peaceful filter feeders that fight only in self-defense. In war they are prized for being nearly invisible to sonar and silent in the water.', 'Rifts World Book 32: Lemuria p.178-179'),
('narcassai-swordfish', 'Narcassai Swordfish', 'monster', 'rifts', 0, 'Considered Miscreant', '{"IQ":"1D6+3","ME":"1D6+1","MA":"1D6","PS":"2D4+24","PP":"1D6+12","PE":"1D6+10","PB":"1D6+9","Spd":"4D6+76"}', NULL, NULL, 'PEx10', '1D6x10', NULL, 'I.Q. is animal intelligence. P.S. is Robot equivalent strength. Spd is swimming (on average 60 mph/96 km or 52 knots). On S.D.C. worlds: 6D6+12 Hit Points, 2D4x10 S.D.C. and a Natural A.R. of 9.', NULL, 12, '{"attacks":3,"initiative":3,"strike":4,"dodge":5}', '+1 to Perception Rolls, +3 on initiative, +4 to strike and +5 to automatic dodge (dodging does not use up a melee attack), in addition to possible attribute bonuses. The diving/torpedo charge uses all three attacks of the melee round.', 'Equivalent skills: Swimming 98% and Underwater Navigation 90%.', 'Extremely fast swimmer. Dives as deep as 1,000 feet (305 m) in a plunge and breaches to a height of 15 feet (4.6 m). Sees excellently underwater and has Nightvision to 600 feet (183 m), scents blood from one mile (1.6 km) off, and tolerates depths of 8 miles (12.8 km). Its special power is the Phase Shift Sword: for 5 P.P.E. the bill turns intangible for a few seconds and slides out of whatever it is lodged in after an impaling strike; the fish uses this only to free the bill or get away quickly. Vulnerability: it picks fights with things too tough for it, though its speed lets it flee.', 'None.', 'None.', '12-18 feet (3.6 to 5.4 m) long', '1,200 pounds (540 kg) to one ton', '1D6+10 years', 'All Earth''s oceans and seas, but favors Pacific waters', 'None; a lone hunter that avoids even its own kind except to mate. Some Serpent Hunters ride one as a fast mount, but it follows orders poorly and Lemurian attempts to tame it have failed. Merans, Ichthyleans and Naut''Yll hate and fear it.', 'None per se; treats most creatures smaller than itself as potential prey', 'No O.C.C.; an alien predator classed as a sea monster. Also known as Pepehi Kohe-ta ama I''a, Blood Swordfish and Phase Swordfish. Value: the meat is delicious but few dare hunt it. Against vampires and the rest of the undead the sword bill''s damage counts as Hit Point damage.', 'An oversized swordfish from another world, purple and red with a pale blue belly, that hunts humanoids as readily as fish, birds and mammals. It hunts alone at great speed, either flailing its bill to batter and slash or driving it through the victim like a torpedo, then shaking a man-sized catch until a limb comes off or the body parts in two. It is known to hole boats and pick off the crew in the water. When the bill sticks fast, the fish makes it intangible for about six seconds and swims free.', 'Rifts World Book 32: Lemuria p.179-180'),
('saber-toothed-sea-lion', 'Saber-Toothed Sea Lion', 'monster', 'rifts', 0, 'Considered Anarchist', '{"IQ":"1D6+2","ME":"2D6","MA":"2D6","PS":"2D6+16","PP":"2D6+7","PE":"1D6+18","PB":"1D6+8","Spd":"2D6+34"}', NULL, NULL, 'PEx6', '3D6+5', NULL, 'I.Q. is animal intelligence. P.S. is Supernatural. Spd 2D6+34 is swimming (30 mph/48 km or 26 knots); crawling on land it is only 1D6+2. On S.D.C. worlds: P.E. attribute number x2 Hit Points, 2D4x10+18 S.D.C. and A.R. 10.', NULL, 12, '{"attacks":5,"initiative":2,"strike":3,"pull":3,"roll":3}', 'Horror Factor 12 for one, 15 when facing a pack. +1 on Perception Rolls (+3 if based on sound), +2 on initiative, +3 to strike, +4 to strike with a knockdown attack/tail sweep, +2 to dodge underwater only, +1 to disarm, +4 to entangle/pin, +3 to pull punch and +3 to roll with impact, in addition to possible attribute bonuses. Vulnerabilities: clumsy, slow and exposed on land, though it survives hours out of water; sonic based attacks and explosions do double damage.', 'Equivalent skills: Detect Ambush 40%, Prowl 45%, Swimming 97%, Track and Hunt Sea Animals 75%, Underwater Navigation 98%, and Wrestling.', 'Holds its breath as long as 40 minutes. Good eyesight and a keen nose (track by scent 55%). Cold does half damage. Depth tolerance 2 miles (3.2 km). Bio-regenerates 1D6 M.D.C. an hour. Sense Magnetic North: works as it does for dolphins and whales. Heightened hearing: hears into the ultra-high frequency range. Sonic Echolocation and Ultrasonic Probe: both as a dolphin. Ultrasonic Communication: talks to its own kind in ultrasonic whistles, clicks, hums and reverberations, and answers spoken human commands the way a dog does. Entangle/Pin (special): a tail or fin sweep (5D6 S.D.C. or one M.D.) knocks the target down, then the animal holds him under its tail, a fin and half its weight, or its whole seated bulk, so he cannot bring arms or weapons to bear on it. Two melee attacks, one to knock down and one to pin; the target may dodge each.', 'None.', 'None.', '6-8 feet (1.8 to 2.4 m) for adolescents; 10-18 feet (3 to 5.5 m) for adults', '500-1,000 lbs (225 to 450 kg) for adolescents, 2 tons for adults', '50-60 years in the wild, 100 to 120 years in the care of Lemurians', 'Prefers cold coastal waters but hunts throughout the oceans. Small packs led by a single Lemurian are found all over Lemurian territory and sometimes beyond.', 'Other pack members only; Lemurians, Merans, Ichthyleans and a few other aquatic D-Bees have tamed or taken over packs, which are then fiercely loyal to them', 'Large predators and humanoids, including Horune Pirates and the minions of the Lord of the Deep', 'No O.C.C.; a pack animal kept as a mount, pet or guard beast. Other names: Niho-Peata Sila, meaning Shark Toothed Seal; Saber-Tooth Walrus; Saber Seal. Adolescents are typically the attack dogs and adults the preferred riding size. Value: 6,000-12,000 credits in Lemuria as a trained riding or guard animal, three times that among surface dwellers and pirates.', 'A huge sea lion with a heavy lower jaw from which a pair of saber teeth jut upward. Thick-hided, muscular and fiercely territorial, they hunt fish and seals along the coast in groups and go into deep water as a pack after bigger game. That pack instinct lets a strong master lead them, best when raised from a pup, and a tamed one is loyal enough to die for its rider. Serpent Hunters and Oceanic Guardsmen ride them standing or crouched like a jockey; Merans, Amphibs and Naut''Yll more often keep them as watch animals.', 'Rifts World Book 32: Lemuria p.180-181'),
('sea-dragon-turtle', 'Sea Dragon Turtle', 'monster', 'rifts', 0, 'Principled (40%), Scrupulous (50%) or Unprincipled (10%)', '{"IQ":"2D4+8","ME":"2D4+14","MA":"2D4+10","PS":"4D4+24","PP":"2D4+3","PE":"2D4+20","PB":"3D4+8","Spd":"1D4x10+40"}', NULL, NULL, '3D4x100', '2D4x10+PE', 'MEx3', 'I.Q. is generally considered high animal intelligence. P.S. and P.E. are Supernatural. Spd 1D4x10+40 is swimming and is tripled along ley lines; on land it is 1D4+4. I.S.P. is M.E. attribute number x3 plus 1D4 per level of experience. Experience Level: 1D4, +1 per 100 years of existence. On an S.D.C. world: 1D4x100 Hit Points, 1D6x100 S.D.C. and A.R. 18.', NULL, 14, '{"attacks":4,"strike":2,"pull":4}', 'The 14 is printed as Horror/Awe Factor. +3 on Perception Rolls, +1 to initiative when fighting undead, +2 to strike, +4 to strike with Solar Beam Eyes, +4 to disarm and pull punch, +2 to dodge when underwater only, +6 to save vs possession and mind control, in addition to possible attribute bonuses. Darkness (vulnerability): without 14 hours of sunlight a week, halve all physical attributes, attacks, eye beam damage, bonuses and P.P.E., skills are -10%, and it cannot make Sunstones. After more than two weeks without light it loses the eye beams, skills are -30%, Bio-Regeneration stops and it starves at 1D4x10 M.D.C. a week. Seven hours of sunbathing stops the M.D.C. loss; 28 hours of light over a week restores it fully.', 'Equivalent skills: Swimming 98%, Astronomy and Navigation 84%, Dowsing 64%, Identify Plants & Fruit 78%, Land Navigation 70%, Mathematics: Basic 84%, Tailing (underwater only) 70%, Underwater Navigation 88%, and Wilderness Survival 88%. All skills except Swimming advance 1% per level of experience.', 'Nightvision 600 feet (183 m); sees every spectrum of light, ultraviolet and infrared included; polarized vision that glare cannot dazzle or blind; extraordinary hearing; fire, heat and cold do half damage, magical or not; depth tolerance 8 miles (12.8 km); regenerates 1D4 M.D.C. each melee round. Absorb Sunlight (special): lives on sunlight and needs 14 hours of it a week, in one stretch or spread out. Amphibious (special): lives on land or in water without limit but breathes air, holding its breath two hours per P.E. point. Chemoreceptors (special): tastes the salt and toxins in water and follows food by taste, 60% +5% per level to track and 40% +5% per level to identify chemicals, toxins or particular creatures. Create Sunstone (special): up to once a month, for 40 P.P.E., it coughs up a rough yellow magic stone as big as a basketball with 1D4+4 M.D.C. The stone shines like the Globe of Daylight spell, radius 30 feet (9.1 m), for 12 hours, lights a 50 foot (15 m) radius well enough to read by on the sea floor, and recharges after two hours in bright sun. Struck against an evil supernatural or undead creature it bursts, dealing the undead 1D4x100 Hit Points/M.D. and blinding anyone caught unprepared for 1D4 melee rounds; good mortals and good supernatural beings are untouched, selfish supernatural ones merely uneasy. Devour the Undead (special): undead it kills and eats are destroyed for good. Sense Magnetic Fields (special): Sense Magnetic North and Undersea Navigation 98%, and it feels the fields of electrical cable, iron ships and rail guns. Its special Sun Aura is a warm glow that is not blinding; for undead and evil supernatural beings hurt by sunlight it works as Globe of Daylight and holds them 100 feet (30.5 m) from the turtle and whoever swims beside it. Solar Eye Beams (special): see attacks.', 'None.', 'Empathy (4), Meditation (0), Psychic Diagnosis (4), See Aura (6), See the Invisible (4), Sense Evil (2), Sense Time (2), and Suppress Fear (8). I.S.P. is M.E. attribute number x3 + 1D4 per level of experience.', '40-50 feet (12 to 15 m) long from nose to end of the shell; tail adds 12-15 feet (3.6 to 4.6 m) and the neck can stretch 15 feet (4.6 m). Height 15-20 feet (4.6 to 6.1 m), shell width 25-35 feet (7.6 to 10.6 m), leg span 50-65 feet (15.2 to 19.8 m) when extended to swim', '12-30 tons', 'Printed as "P.E. attribute number 30" (apparently P.E. x30 years)', 'Oceans and seas around the world; as many as 2D4x10 gather around Lemurian outposts, gardens and cities. Travels alone, as a pair (often mates) or in groups of 2D4.', 'Lemurians, Merans, Ichthyleans and all humanoids of good alignment; leery of Unprincipled and distrustful of Anarchist and evil alignments', 'Supernatural evil and the undead, including zombies and animated dead, and above all the Milu and the minions and undead servants of the Lord of the Deep, Davey Jones and the Splugorth. Naut''Yll and Horune Pirates also hunt or enslave them.', 'No O.C.C. The Experience Level line reads 1D4, +1 per 100 years of existence, and adds that the turtle is not recommended as a player character; the entry gives no rules for playing one, so it is treated as an NPC ally and mount. Other names: La Mo''o Kea, meaning Sun Lizard Tortoise; Giant Solar Turtle; Sun Turtle. Value: a good-luck sign that seafarers of good alignment rarely hunt; Anarchist and evil hunters, Horune Pirates and slavers among them, take the M.D.C. shell, horns, meat and oils. Heavy body armor of Sun Turtle shell: 3D4+90 M.D.C., 60 pounds (27 kg), -15% to Physical skills such as Climbing and Prowl but +5% to Swimming, non-environmental, 35,000-45,000 credits.', 'A colossal sea turtle from another dimension with a long head, two goat-like horns and a thin beard, its finned shell so overgrown with algae that a floating one passes for an islet. Not a true dragon, it is a Creature of Light that feeds on sunshine: it basks by day, then dives to hunt, kill and eat undead, demons and other things of darkness, loosing its stored light in the deep. It senses goodness and rescues, carries and guards good people, and willingly serves Lemurians as mount, war steed, heavy combat platform and royal escort. Lemurians rate it nearly as bright as a human.', 'Rifts World Book 32: Lemuria p.182-184'),
('storm-crab', 'Storm Crab', 'monster', 'rifts', 0, 'Considered Anarchist', '{"IQ":"1D4+3","ME":"2D6+4","MA":"2D6","PS":"3D6+38","PP":"1D6+15","PE":"1D6+15","PB":"1D6+1","Spd":"2D6+20"}', NULL, NULL, '1D6x100+760', '1D4x100', NULL, 'M.D.C. by location: Eye Stalks (two, small) 45 each; Legs (6) 300 each; Pincer Arms (2) 500 each; Main Body (top) 1D6x100+760; Main Body (underbelly) 1D6x100+150. The mdc pool is the Main Body (top). Eye stalks are -6 to strike with a ranged weapon; losing both is only a -3 blindness penalty, and they grow back in days. I.Q. is animal intelligence. P.S. and P.E. are Supernatural. Spd 2D6+20 is on dry land (18 mph/29 km on average); half that scuttling on the sea floor or swimming (9 mph/14.4 km or 7.8 knots). P.P.E. recovers 1D4x10 per hour. On an S.D.C. world: 1D4x100+64 Hit Points, 2D6x100 S.D.C. and A.R. 17.', NULL, 14, '{"attacks":4,"initiative":2,"strike":2,"parry":4,"pull":6,"roll":2}', 'Horror Factor 14 underwater, 16 on the surface with the electrical discharges and rolling fog. +2 on initiative, +2 to strike, +3 to strike with each lightning blast, +4 to parry, +6 to pull punch, +2 to roll with impact, +1 on all saving throws, impervious to electricity and resistant to cold, in addition to possible attribute bonuses. Vulnerabilities: comparatively slow, poor eyesight (it leans on its other senses) and a huge target that draws fire. Lightning and static fog do not work while it is submerged.', 'Equivalent skills: Climbing 65%, Detect Ambush 45%, Excavation 55%, Hunting Prowl 40% (underwater only), Swimming 60% (neither a strong nor a fast swimmer), Tailing 60% (underwater only), Track (by sight and smell) 60%.', 'Walks and runs forward, backward and sideways; leaps 40 feet (12.2 m) up or across as two melee actions; breathes water and air. Electricity cannot hurt it, magical and M.D. lightning included, nor can Ley Line Storms; sonic attacks and cold do half damage; depth tolerance 6 miles (9.6 km). Amphibious (special): lives on land or in the sea without limit. Bio-Regeneration (special): 1D4x10 M.D.C. a minute; eyes and eye stalks regrow in 1D6 days, legs in 2D4 weeks, a pincer in 3D4 weeks, all in half the time if it waits at a ley line. Chemoreceptors: tastes salinity and toxins and tracks food through water at 60%, identifies chemicals, toxins or particular creatures from taste trails at 40%, and on the surface smells ozone and coming storms at 60% (+15% for Ley Line Storms). Create Static Fog: only at the surface along a shoreline, it churns the sea electrically into a mist 200 feet (61 m) in radius and as much as 60 feet (18.3 m) high around itself and its riders; the mist lasts while the crab keeps making it and 5D6+6 minutes more, but wind of 25 mph (40 km) or better scatters it. Electrical Discharge/Lightning: see attacks; each bolt costs 10 P.P.E., the electrified claw and underbelly cost none. Electromagnetic Sense: feels electromagnetic fields, current and the bio-electric impulses of living things around it like radar, knows magnetic north and senses incoming rail gun barrages.', 'None, other than the natural and instinctive use of P.P.E. to create electricity and fire lightning bolts.', 'None.', 'Adult body 50-70 feet (15.2 to 21.3 m) in diameter; 100-120 feet (30.5 to 36.6 m) wide with the legs extended; stands 30-40 feet (9.1 to 12.2 m) tall; claws reach 25 feet (7.6 m)', '120-200 tons', '700-1,000 years', 'From another world but well adapted to Rifts Earth; found anywhere in the wild, mostly Pacific waters. Every Lemurian city and secret Garden keeps from a dozen to 2D4 dozen as living tanks and heavy construction animals.', 'Respectful of certain humanoids, primarily Lemurians and Merans, who raise and tame them as work, riding and battle animals; few others have the patience or ability to control one', 'Sea monsters and surface dwellers prey on the young and are preyed on by the adults. Humanoids hunt them for armor, meat and organs, or for the arena. An omnivore that treats most creatures under 50 feet (15.2 m), humans and D-Bees especially, as potential prey.', 'No O.C.C.; the Lemurian Oceanic Guardsmen''s living battle tank, troop carrier and artillery piece. Lemurian names: Ino Papa''I, meaning Storm Crab, and Hekili ''ino Papa''I, meaning Thunderstorm Crab. Value: about 10 million credits as a monstrous pet or mount. The shell can be made into M.D.C. armor or building material only if cured correctly, a secret kept by Horune Pirates, Metztla, Lemurians and a few others; simply dried it turns brittle at one-tenth the M.D.C. Heavy body armor of Storm Crab shell: 6D6+120 M.D.C., 50 pounds (22.5 kg), -15% to Physical skills such as Climbing and Prowl and -10% to Swimming, non-environmental, 45,000-50,000 credits. The meat brings 20 credits a pound.', 'A tank-sized amphibious crab from another world, bred and trained by Lemuria as frontline armor, troop transport and artillery. Slow but very hard to stop, it relies on a thick M.D.C. shell, giant pincers and Supernatural Strength. Coming ashore it crackles with lightning that raises a mist and then a small rolling thunderstorm, and it uses that charge to blast enemy positions and troops. None of the electrical display works under the surface. Lemurians also use them as heavy digging and excavation animals.', 'Rifts World Book 32: Lemuria p.184-186'),
('terror-eel', 'Terror Eel', 'monster', 'rifts', 0, 'Considered Miscreant or Diabolic', '{"IQ":"1D4+3","ME":"1D6+8","MA":"1D6","PS":"1D6+11","PP":"1D6+19","PE":"1D6+13","PB":"2D6","Spd":"2D6+20"}', '4D6+6', '1D6x10', NULL, '1D6', NULL, 'An S.D.C. creature with a Natural A.R. of 8. I.Q. is animal intelligence, but they are cunning hunters. Spd is swimming (18 mph/29 km or 15.6 knots).', 8, 10, '{"attacks":3,"initiative":2,"strike":2,"dodge":1}', 'Horror Factor 10 on their own, 15 as a pack making all kinds of scary noises. Three attacks per eel; pack members take turns attacking while keeping up the Terror Shriek. +2 to initiative, +3 on Perception Rolls, +2 to strike, +1 to dodge, in addition to possible attribute bonuses; +6 to save vs Horror Factor. Vulnerability: cocky, and may underestimate stronger prey by trusting in fear, which fails against some creations of the Lord of the Deep, sea dragons and other powerful underwater supernatural creatures.', 'Equivalent skills: Imitate Voices (30%) and Sounds 80%, Prowl 80%, Swimming 98% and Tailing 85%.', 'Nightvision 2,000 feet (610 m). Cold does half damage, though magical cold does full. Depth tolerance 7 miles (11 km). Keen hearing finds anything moving in the water at 90% and picks up prey as far off as 3,000 feet (914 m). Nearly fearless, and every eel knows how to fight as part of a team. Terror Shriek (special): the Warning Shriek carries Horror Factor 10, the Attack Shriek 13 and the Terror Shriek 15, and the last is painful to most animals'' ears. It stuns small fish and disorients dolphins, orca and most humans and D-Bees: attacks per melee and combat bonuses are halved, initiative is lost and skills are at -30%. Anyone on listening gear must switch it off or take the same penalties. Radio traffic breaks up into static and squeals, and sonar is at -50% for an accurate reading and -4 to strike with sonar or sound-based targeting.', 'None.', 'Empathy, always on at no I.S.P. cost; they feel the emotions of those around them and become excited in the presence of fear.', '7-10 feet (2.1 to 3 m) long', '90-130 lbs (40.5 to 58.5 kg)', '15-30 years', 'Anywhere in the Pacific and other tropical oceans and seas. They can live very deep but prefer coastal waters and reefs, and go wherever prey is plentiful, populated coasts included.', 'Fellow Terror Eels only. The average pack is 1D6+4 members, sometimes as large as 2D6+6 (the opening text gives schools of 1D4+4).', 'None per se; they hunt just about anything they think they can kill', 'No O.C.C.; an S.D.C. pack predator. Also known as Scream Eels or Screaming Eels. Value: none, though some tribal people eat them.', 'A black-scaled, red-eyed eel that hunts in packs and screams its prey senseless before closing in. Members rotate, some biting while others keep up the noise, and they are skilled at cutting a single man-sized or dolphin-sized victim out of its group. They toy with a catch before the kill. Their clicks, whistles and mimicry lure the unwary, including a cry like a weeping woman or child, and they have learned to patrol beaches and trail boats because humans and D-Bees are easy meals. Old eels show silver or white streaks along scales and spine fins.', 'Rifts World Book 32: Lemuria p.186-187'),
('twisted-treasure-seahorse', 'Twisted Treasure Seahorse', 'monster', 'rifts', 0, 'Considered Anarchist in the wild; as a Familiar or pet its alignment mirrors its master''s', '{"IQ":"1D6+8","ME":"1D6+9","MA":"1D6+9","PS":"1D6","PP":"1D6+7","PE":"1D6+9","PB":"2D6+11","Spd":"1D6+16"}', NULL, NULL, '1D6+6', '6D6+10', 'MEx3', 'I.Q. is high animal intelligence. P.S. and P.E. are Supernatural. Spd is swimming or flying (12 mph/19.2 km or 10 knots) and is doubled along ley lines. On an S.D.C. world: P.E. attribute number Hit Points, 4D6 S.D.C. and A.R. 8. No Horror Factor is printed.', NULL, NULL, '{"attacks":2,"initiative":1,"dodge":3}', '+6 on Perception Rolls, +1 on initiative, +3 to dodge, +4 to save vs Horror Factor and +7 to save vs illusions, in addition to possible attribute bonuses. A power punch counts as two attacks.', 'Equivalent skills: Detect Ambush 80%, Detect Concealment 75%, Detect Traps and Mines 70%, Dousing 90%, Find Contraband 60%, Gardening 65%, Identify Plants & Fruit 80%, Land Navigation 75%, Lore: Demons & Monsters 60%, Prowl 70% (+10% underwater), Swimming 98%, Tailing 88%, Track and Hunt Sea Animals 60%, Tracking (Humanoids) 65%, and Underwater Navigation 88%.', 'Swims and flies, breathes air and water alike, takes half damage from fire, heat and cold, tolerates 4 miles (6.4 km) of depth and regenerates one M.D.C. a melee. Fly in Air (special): hovers, floats, glides and flies under its own power to a ceiling of 2,000 feet (610 m) at 12 mph (19.2 km); flying and swimming speed double on a ley line. Its special innate understanding of people and emotions: it senses what others feel and is drawn to goodness, joy and laughter; strongest when bound to a mage as a Familiar, when it anticipates its master''s needs. Light-Up Fin Tips (special): fin and frill tips glow at will, about a 40 watt bulb''s worth over a 4 foot (1.2 m) radius, for seeing or signalling; on a ley line they light by themselves at double brightness and triple range. Limited Amphibious Nature (special): stays airborne out of water two hours per P.E. point. It cannot walk or crawl but climbs bushes and trees and swings from branches and vines. Past its limit it dehydrates and dies in 1D6+1 hours, with M.D.C., P.P.E., I.S.P., attacks and bonuses halved every hour; put back in the sea in time it recovers fully in 1D6 hours. Vision, Full Spectrum: sees infrared, ultraviolet, electromagnetic energy and magic energy. Prehensile Tail: more dexterous than a monkey''s and far stronger; it works buttons, levers and doorknobs and hauls anything with a handle or rope to grip, up to 100 pounds (45 kg).', 'None, but when the animal is a Familiar the sorcerer can draw upon up to two thirds of its P.P.E. reserve.', 'Empathy (4), See Aura (6), See the Invisible (4), Sense Magic (3), Sense Evil (2) and Telepathy (4). Base I.S.P. is M.E. attribute x3.', '8-12 inches (20 to 30 cm) tall, with a tail that uncurls for an additional 12 to 20 inches (30 to 51 cm)', '2-5 lbs (0.9 to 2.3 kg)', '200-600 years', 'Oceans and seas worldwide, with a strong preference for tropical coral reefs; also lives in Lemurian undersea gardens and cities', 'Lemurians, Merans, Ichthyleans and others who show good intentions, good alignment and compassion; attracted to goodness and beauty, and likes humans, though it has little contact with surface people', 'Sea monsters and evil supernatural beings; regards the Splugorth, the Lord of the Deep, the Milu, demons and undead as natural enemies', 'No O.C.C.; a favorite Familiar of Ocean Wizards, Aquatic Biomancers and Sea Druids. Other names: Kopeka Kura Moana Lio; Whina Moana Lio, meaning Helper Seahorse; Treasure Seahorse for short. Value: 100,000 to 500,000 credits, or even a million, as a companion or familiar. Lemurians never trade in them; they invite one to become a partner instead.', 'A foot-tall seahorse with turquoise or blue skin traced in gold veins that looks ordinary but is an M.D.C. being with odd powers. Sea mages keep them as Familiars: one rides on a cloak, necklace, belt or lock of hair, drifts at its master''s shoulder, or slips ahead to scout and spy. They are sharply observant and, as Familiars, attuned to the master''s feelings more closely than any other familiar animal.', 'Rifts World Book 32: Lemuria p.187-189'),
('panther-shark', 'Panther Shark', 'monster', 'rifts', 0, 'Any; most are Scrupulous (40%), Unprincipled (30%) or Anarchist (20%)', '{"IQ":"1D4+5","ME":"1D6+10","MA":"1D6+3","PS":"1D6+20","PP":"1D6+18","PE":"2D6+12","PB":"1D6+6","Spd":"2D4+60"}', NULL, NULL, '3D6x10+70+PE', '5D6+5', NULL, 'Lemurian War Steed, also called Devil Shark and Running Shark. I.Q. is high animal intelligence; P.S. and P.E. are supernatural. Spd is running (40 mph/64 km); swims at 30 mph (48 km or 26 knots). Along a ley line running speed rises 50% and swimming speed 30%. Full speed lasts 30 minutes running (one hour swimming) per P.E. point, then one third speed for half as long, then at least five hours of rest. A leisurely pace lasts one hour per P.E. point. M.D.C. is 3D6x10+70 plus the P.E. number. On S.D.C. worlds: 2D6x10+40 Hit Points, 2D4x10 S.D.C. and Natural A.R. 14.', NULL, 14, '{"attacks":4,"initiative":3,"strike":3,"parry":4,"dodge":4}', 'In addition to attribute bonuses: +2 on Perception Rolls involving blood, hunting and combat, +3 initiative, +3 strike, +4 parry, +4 automatic dodge on land and in water, +6 to save vs Horror Factor. Cannot do a power bite; a power claw strike counts as two melee attacks. Will not head butt, stomp or ram.', 'Equivalent skills: Climbing 88%/55%, Land Navigation 90%, Tailing 85% (on land and underwater), Tracking people or animals on land 65% (+15% on a blood scent), Underwater Navigation 90%. Picks up spoken languages quickly (65%); understands Lemurian and Oceanic at 90%.', 'Swims at 98% and breathes air or water for as long as it likes. Withstands depths of five miles (8 km). Nightvision 1,000 feet (305 m) with fine day and underwater sight. Underwater it tracks by smell alone at 75% (+20% on a blood trail). Cold does half damage. From a standstill it leaps 40 feet (12.2 m) up or across, half again as far with a run. Heals 2D6 an hour (roughly 120-180 points a day). Pounce Attack (special): with the belly blades out a pounce does 6D6 M.D., and a target who fails to roll with impact is knocked down, loses initiative and one melee attack, and is pinned on 01-60%. A pinned victim has half his attacks and is -5 to strike, parry and dodge while the steed bites and its rider strikes.', NULL, NULL, '14-18 feet (4.3 to 5.5 m) long from snout to rump plus 6-8 feet (1.8 to 2.4 m) of tail; 5-6 feet (1.5 to 1.8 m) wide and 7-9 feet (2.1 to 2.7 m) tall at the shoulders; the fin adds 4 feet (1.2 m)', '2-3 tons; females tend to be 25% larger than males', '1D6x10+60 years', 'At home hunting and fighting on land or at sea, though the ocean is where it lives.', 'Lemurians, who made it; humans and aquatic D-Bees may also use one. Gets on with other sharks; most mammals and sea life treat it as a dangerous predator.', 'Large marine predators, sea serpents, sea monsters, humanoids and the enemies of Lemuria', 'No O.C.C.; a riding animal bred by Lemurian Gene-Mages, favored by Oceanic Guardsmen, Scouts and Serpent Hunters. Value: 500,000 credits trained; the section says a steed that reaches the open market often brings 50% to 200% more. Hide is useless for armor; teeth become arrowheads, knives and war clubs, belly blades become knives, short swords and spearheads; a whole carcass sells as meat for 300-500 credits.', 'A huge gray shark on four clawed legs with a white belly, bred as a mount for work ashore. It runs, climbs, leaps and pounces as readily as it swims, parries and rips with its fore-claws, and carries a row of blade-like spikes under its belly that fold away or swing out to cut whatever it jumps over or lands on. Disposition: aggressive and cunning, a born predator that lives to stalk and fight, fearless, yet dependable and loyal to its rider.', 'Rifts World Book 32: Lemuria p.189-190'),
('sea-lance', 'Sea Lance', 'monster', 'rifts', 0, 'Any; most are Principled (30%), Scrupulous (30%), Unprincipled (20%) or Anarchist (10%)', '{"IQ":"1D4+7","ME":"1D6+14","MA":"1D6+18","PS":"1D6+15","PP":"1D6+14","PE":"1D6+14","PB":"1D6+14","Spd":"2D4+50"}', NULL, NULL, '1D6x10+55', '6D6+20', NULL, 'Lemurian War Steed, also called Winged Dolphin and Ocean Unicorn. I.Q. is high animal intelligence, short of sentient cetaceans; P.S. and P.E. are supernatural. Spd is running (36 mph/57.6 km); double in water (72 mph/115 km or 62 knots). Running and swimming speed double along a ley line (the stat block says so twice; the entry''s opening text says it runs 50% faster on a ley line). Full speed lasts one hour per P.E. point, then half speed for half as long, then at least five hours of rest; a leisurely pace is indefinite. M.D.C. by location: Horn (1) 2D6+6; Head 5D6+40; Large Wing Fins (2) 1D6x10+45 each; Small Wing Fins (2, on front legs) 3D6+22 each; Legs (4) 1D4x10+50 each; Tail 1D4x10+50; Main Body 1D6x10+55.', NULL, 11, '{"attacks":4,"initiative":2,"strike":3,"parry":1,"dodge":4,"pull":3,"roll":3}', 'Horror/Awe Factor 11. In addition to attribute bonuses: +3 on Perception Rolls, +2 initiative, +3 strike, +1 parry, +4 automatic dodge in air, in water and on land, +3 pull punch, +3 roll with impact, +4 to save vs Horror Factor, +1 to save vs illusions and mind control. Cannot do a power bite or kick; the underwater ram counts as two melee attacks.', 'Equivalent skills: Land Navigation 80%, Tailing 75% (on land and underwater), Prowl 50%, Underwater Navigation 90%. Picks up spoken languages quickly (75%); understands Lemurian and Oceanic at 90%.', 'Swims at 98% and holds its breath 30 minutes plus 2 minutes per P.E. point. Withstands depths of four miles (6.4 km). Nightvision 1,000 feet (305 m) with fine day and underwater sight. Cold does half damage. Heals 1D6 an hour (about 80 points a day). Flying/Gliding: it can burst from the sea and glide 10-20 feet (3-6.1 m) over the waves for as far as 200 feet (61 m), or jump up onto a deck or other surface as much as 40 feet (12.2 m) above the water, always landing on its feet. Ley Line Flying: only on a ley line does the glide become true flight, at running speed, 36 mph (57.6 km), to a ceiling of 600 feet (183 m).', NULL, NULL, '14-18 feet (4.3 to 5.5 m) long from snout to tail tip, 3-4 feet (0.9 to 1.2 m) wide at the shoulders; wingspan 18 feet (5.5 m) fully extended', '800-1,200 pounds (360 to 540 kg); males tend to be 20% larger than females', '1D6x10+30 years', 'Wherever Lemurians live, above all their cities, gardens and outposts. The ocean is home, but it does well on dry land when there is water nearby to swim in.', 'Chiefly Lemurians, who made it; humans and aquatic D-Bees may also use one. Gets on with other cetaceans and is fond of Sea Whips, Serpent Seals and other playful animals and kind people; small fish and crustaceans treat it as a dangerous predator.', 'Sharks and large marine predators, sea serpents, sea monsters, humanoids and the enemies of Lemuria', 'No O.C.C.; a riding animal bred by Lemurian Gene-Mages, favored by Scouts, explorers, Biomancers and other magic users. Value: 150,000-200,000 credits trained; the section says a steed that reaches the open market often brings 50% to 200% more. Hide is useless for armor; the horn alone can be made into a stabbing weapon or spearhead (1D6 M.D.). Nobody buys the meat.', 'The smallest and least alarming of the Lemurian mounts: a horned, four-legged dolphin with wing-like fins. It swims with a dolphin''s motion, and its wings carry its leaps from the water far enough to land on ships, docks and beaches. It has the thinnest natural armor of the steeds, so it usually wears Bio-Barding. Disposition: gentle, easygoing, helpful and playful; unshakable in a fight, it will not desert its rider and has died defending him or innocents, children above all.', 'Rifts World Book 32: Lemuria p.191-192'),
('sea-saber', 'Sea Saber', 'monster', 'rifts', 0, 'Any; most are Principled (20%), Scrupulous (30%), Unprincipled (20%) or Anarchist (20%)', '{"IQ":"1D4+6","ME":"1D6+12","MA":"1D6+15","PS":"1D6+24","PP":"1D6+14","PE":"1D6+14","PB":"1D6+14","Spd":"2D4+72"}', NULL, NULL, '2D6x10+70', '1D6x10+35', NULL, 'Lemurian War Steed, also called Sea Cat and Wind Cat. I.Q. is high animal intelligence, short of sentient cetaceans; P.S. and P.E. are supernatural. Spd is running (58 mph/93 km). Runs or swims at full speed one hour per P.E. point, then needs at least six hours of rest; a leisurely pace lasts twice as long. M.D.C. by location: Head 6D6+60; Manta Tail Section & Wings (2) 2D4x10+45 each; Fish-Wings (2, back) 1D6x10+40 each; Back Fin (1) 1D6x10+70; Legs, Front (2) 1D6x10+60 each; Legs, Rear (2) 2D6x10+50 each; Main Body 2D6x10+70.', NULL, 13, '{"attacks":5,"initiative":3,"strike":4,"parry":3,"dodge":3,"pull":3,"roll":4}', 'In addition to attribute bonuses: +3 on Perception Rolls, +3 initiative, +4 strike, +3 parry, +3 automatic dodge in air, in water and on land, +3 pull punch, +4 roll with impact (and lands on its feet on a success), +5 to save vs Horror Factor. Cannot do a power bite or power claw strike.', 'Equivalent skills: Climbing 95%/70%, Land Navigation 90%, Tailing 85% (on land and underwater), Prowl 75% (on land and underwater), Track Animals 75% (on land), Underwater Navigation 90%. Picks up spoken languages quickly (65%); understands Lemurian and Oceanic at 90%.', 'Swims at 98%, breathes water and air without limit, Nightvision 1,000 feet (305 m), fine day and underwater sight, half damage from cold, heals 1D6 an hour (about 80 a day). Depth tolerance four miles (6.4 km), though it favors sunlit shallows. Climbing: scales a steep slope or sheer wall at half running speed for 15 stories, one third above that. Leaping: 60 feet (18.3 m) up and across from standing, double with a run. Gliding Leap: to 200 feet (61 m), double with a strong tailwind or on a ley line, as high as 100 feet (30.5 m). Flying: rides the wind at up to 20 mph (32 km) over wind speed, ceiling 1,000 feet (305 m); with wind above 20 mph or its bio-thrusters lit, triple air speed and a one mile (1.6 km) ceiling. Must leap to take off; hovers 1D4+1 minutes. Thrusters burn five minutes per P.E. point in air. In Water: drifts at current speed, swims at 50 mph (80 km or 43 knots), and makes 80 mph (128 km or 69.5 knots) on thrusters for 10 minutes per P.E. point. Ley lines add 50% to air and water speed and duration.', NULL, NULL, '14-17 feet (4.3 to 5.2 m) long from snout to rump plus 11-13 feet (3.3 to 3.96 m) of manta-wing tail; 4-5 feet (1.2 to 1.5 m) wide at the shoulders; manta-wingspan 12-15 feet (3.6 to 4.6 m)', '1-2 tons; males tend to be 20% larger than females', '1D6x10+30 years', 'Wherever Lemurians live, above all their cities, gardens and outposts. The ocean is home, but it thrives ashore and likes to explore and hunt on islands and in coastal forests.', 'Chiefly Lemurians, who made it; humans and aquatic D-Bees may also use one. Gets on with other cetaceans, Sea Whips, Serpent Seals, Serpent Seahorses and other playful animals. Wary of strangers, and regards most fish and mammals, people included, as possible prey.', 'Sharks and large marine predators, sea serpents, sea monsters, humanoids and the enemies of Lemuria', 'No O.C.C.; a riding animal bred by Lemurian Gene-Mages, favored by Oceanic Guardsmen and, when they ride at all, Sea Sentinels. The rider crouches like a jockey and steers with two of its feelers. Value: 350,000-600,000 credits trained; the section says a steed that reaches the open market often brings 50% to 200% more. Hide is useless for armor; each of the two saber teeth can serve as a stabbing weapon, pick or spearhead (1D6 M.D.). The meat cannot be eaten.', 'A saber-toothed cat crossed with a manta ray and a fish, built to be quick on land, in water and in the air. It has a tan or brown rubbery hide, green eyes, pearl-white fish-wings on its back and a kite-like manta tail that folds flat when it runs. Biological thrusters behind the shoulders give it bursts of speed. Disposition: alert, quick to act and fierce in battle, otherwise gentle and easygoing; steady under fire and devoted to its rider and its own kind.', 'Rifts World Book 32: Lemuria p.193-194'),
('sea-whip', 'Sea Whip', 'monster', 'rifts', 0, 'Any; most are Principled (30%), Scrupulous (30%), Unprincipled (20%) or Anarchist (10%)', '{"IQ":"1D4+6","ME":"1D6+15","MA":"1D6+15","PS":"1D6+25","PP":"1D6+13","PE":"1D6+14","PB":"1D6+10","Spd":"2D4+50"}', NULL, NULL, '2D6x10+120', '6D6+20', NULL, 'Lemurian War Steed, also called Whip Dolphin and Monster Dolphin. I.Q. is high animal intelligence, short of sentient cetaceans; P.S. and P.E. are supernatural. Spd is running (36 mph/57.6 km); double in water (72 mph/115 km or 62 knots). On a ley line running speed rises 50% and swimming speed doubles. Full speed lasts one hour per P.E. point, then at least five hours of rest; a leisurely pace lasts two hours per P.E. point. M.D.C. by location: Head 1D6x10+80; Fins (2, top) 5D6+20 each; Thruster Jets (6, back) 4D6+35 each; Legs, Front (2) 1D6x10+70 each; Legs, Rear (2) 1D6x10+80 each; Tail 4D6x10+350; Main Body 2D6x10+120.', NULL, 14, '{"attacks":5,"initiative":3,"strike":3,"parry":3,"dodge":2,"pull":5,"roll":2}', 'Horror/Awe Factor 14. In addition to attribute bonuses: +2 on Perception Rolls, +3 initiative, +3 strike with most attacks (+5 with the tail), +3 parry (+4 with the tail), +2 automatic dodge in water and on land, +5 pull punch, +2 roll with impact, +5 to save vs Horror Factor, +1 to save vs illusions and mind control. Cannot do a power bite or power claw strike; the power tail strike counts as two melee attacks.', 'Equivalent skills: Land Navigation 80%, Tailing 75% (on land and underwater), Prowl 50%, Underwater Navigation 90%. Picks up spoken languages quickly (75%); understands Lemurian and Oceanic at 90%.', 'Swims at 98%, breathes water and air without limit, Nightvision 1,000 feet (305 m), fine day and underwater sight, half damage from cold, heals 2D6 an hour (about 140 a day). Depth tolerance four miles (6.4 km), though it favors sunlit water, reefs and the surface. Leaping: 30 feet (9.1 m) up and across from standing, double with a run. Torpedo Speed: an organic rocket system drives it through the water at 130 mph (208 km or 112 knots), under or on the surface, for 20 minutes per P.E. point; a ley line adds 50% to that speed and time. The long prehensile tail ends in a hard, flat paddle that serves as rudder and club; it reaches foes on every side, parries, and can try to bat away incoming missiles.', NULL, NULL, '13-16 feet (3.9 to 4.9 m) long from snout to rump plus an 18-22 foot (5.5 to 6.7 m) tail, of which the paddle is 8-11 feet (2.4 to 3.3 m) long and 4-5 feet (1.2 to 1.5 m) wide; chest and shoulders 8-10 feet (2.4 to 3 m) wide, 3 feet (0.9 m) at the waist', '3-5 tons; females tend to be 10% larger than males', '1D6x10+50 years', 'Wherever Lemurians live, above all their cities, gardens and outposts. The ocean is home, but it does well ashore so long as it can reach somewhere to swim and bathe regularly.', 'Chiefly Lemurians, who made it; humans and aquatic D-Bees may also use one. Gets on with other cetaceans, Serpent Seals and other playful animals and kind people, and loves company; small fish and crustaceans treat it as a dangerous predator.', 'Sharks and large marine predators, sea serpents, sea monsters, humanoids and the enemies of Lemuria', 'No O.C.C.; a riding animal bred by Lemurian Gene-Mages, favored by Oceanic Guardsmen, first responders and Scouts. The rider sits at the narrow waist. Value: 350,000-500,000 credits trained; the section says a steed that reaches the open market often brings 50% to 200% more. Hide is useless for armor; the tail plate alone can be used as M.D.C. building material. Nobody buys the meat.', 'An orca reshaped as a four-legged mount: gray rubbery skin with white throat and belly and black trim, a barrel chest, strong legs for running and jumping, and living thrusters grown into its back. Its weapon is the paddle-tipped tail, which it swings down on enemies as it bounds over them. Disposition: confident and fierce in a fight, yet graceful, playful and gentle with its rider, people and cetaceans; it stays calm under fire and does not leave its rider.', 'Rifts World Book 32: Lemuria p.195-196');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('seal-serpent', 'Seal Serpent', 'monster', 'rifts', 0, 'Any; most are Scrupulous (55%), Unprincipled (30%) or Anarchist (10%)', '{"IQ":"1D6+7","ME":"1D6+10","MA":"1D6+16","PS":"1D6+19","PP":"1D6+16","PE":"2D6+9","PB":"1D6+12","Spd":"1D6+12"}', NULL, NULL, '4D6x10+PE', '5D6+20', NULL, 'Lemurian War Steed, also called Giant Seal and Monster Seal (other entries in the book call it the Serpent Seal). I.Q. is high animal intelligence; P.S. and P.E. are supernatural. Spd is running (it waddles); swimming is Spd x4 (roughly 40 mph/64 km or 34.7 knots). Swims at full speed for hours equal to ''P.E. attribute divided by half'' (as printed); a leisurely pace, swimming or running, lasts one hour per P.E. point. M.D.C. is 4D6x10 plus the P.E. number. On S.D.C. worlds: 2D6x10 Hit Points, 1D6x10 S.D.C. and Natural A.R. 13.', NULL, 10, '{"attacks":4,"initiative":1}', 'Horror/Awe Factor 10. In addition to attribute bonuses: +2 on Perception Rolls, +1 initiative, +1 to strike with bite attacks, +3 to strike with tail attacks, +4 automatic dodge in water (on dry land only the attribute dodge bonus), +4 to save vs Horror Factor. Cannot do a power bite or power claw strike; the power tail strike counts as two melee attacks. 120 degree peripheral vision lets it notice attackers in front while it fights tail-first.', 'Equivalent skills: Land Navigation 65%, Tailing 65% (in or under water only), Underwater Navigation 90%. Picks up spoken languages quickly (80%); understands and speaks Cetacean at 90%, understands Lemurian and Oceanic at 90%.', 'Swims at 98% and holds its breath 30 minutes plus 1 minute per P.E. point. Withstands depths of two miles (3.2 km). Nightvision 1,000 feet (305 m) with fine day and underwater sight, and a nose good enough to track by scent at 45%. Cold does half damage. Heals 1D6 an hour (about 80 points a day). The end of the tail is a rock-hard knob of bone used as a club. Ashore it fights the way a stegosaur would, hindquarters toward the foe and tail raised, with its long neck twisted round to watch.', NULL, NULL, '30-35 feet (9.1 to 10.6 m) long from snout to rump plus 14-16 feet (3.26 to 4.8 m) of tail; 7-8 feet (2.1 to 2.4 m) wide at the shoulder; the neck alone is 10-12 feet (3-3.6 m)', '4-6 tons; males tend to be 25% larger than females', '1D4x10+70 years', 'Wherever Lemurians live, above all their cities, gardens and outposts. Wild ones keep to coastal waters in most climates and seek out other animals and people.', 'Gets along with most aquatic D-Bees, humans, Lemurians and marine mammals', 'Large marine predators, sea serpents, sea monsters, the Milu and their undead, and humanoid hunters from the surface', 'No O.C.C.; a natural sea serpent long kept by Lemurians and other sea peoples as mount, work animal, guardian and pet. Skilled Serpent Hunters and Scouts ride it bareback in a jockey''s crouch, or standing when on the surface or ashore. Value: no price as a steed is printed. The hide makes waterproof light armor (1D4x10+7 M.D.C., -5% Prowl and movement, about 20,000 credits); teeth become knives, short swords and spearheads; the bone tail becomes an M.D.C. surfboard (5D6+8 M.D.C.). A whole carcass sells as meat for 200-600 credits.', 'A giant seal stretched into a serpent, with a long neck, long body and long tail, green or gray-brown above and pale gray or cream below. It is far slower on land than in the sea. Disposition: inquisitive, gentle and playful. Even wild ones romp with whales, seals, otters and dolphins, let swimmers catch a ride, and have saved people at sea by holding up or towing small boats and carrying castaways to shore. Loyal to a rider and capable in a fight.', 'Rifts World Book 32: Lemuria p.196-199'),
('serpent-seahorse', 'Serpent Seahorse', 'monster', 'rifts', 0, 'Any; most are Scrupulous (15%), Unprincipled (25%) or Anarchist (50%)', '{"IQ":"1D4+5","ME":"1D6+15","MA":"1D6+5","PS":"1D6+30","PP":"1D6+12","PE":"1D6+19","PB":"1D6+17","Spd":"2D4+50"}', NULL, NULL, '6D6x10+280', '1D6x10+PE', NULL, 'Lemurian War Steed, also called Armored Seahorse and Gun Horse. I.Q. is high animal intelligence, short of sentient cetaceans; P.S. and P.E. are supernatural. Spd is running (36 mph/57.6 km); swimming is 50% faster (54 mph/86.4 km or 46.9 knots); both double along a ley line. Full speed lasts one hour per P.E. point, then at least three hours of rest; a leisurely pace lasts twice as long. P.P.E. is 1D6x10 plus the P.E. number. M.D.C. by location: Head 1D6x10+130; Shoulder Fin Shields (2) 1D6x10+100 each; Shoulder Stonecasters (2) 90 each; Shoulder Ion Guns (2) 35 each; Back Fin (1) 1D6x10+70; Legs, Front (2) 1D6x10+160 each; Legs, Rear (2) 2D6x10+180 each; Serpent Tail 3D6x10+115; Main Body 6D6x10+280 (470 on average).', NULL, 13, '{"attacks":4,"initiative":3,"strike":4,"parry":1,"dodge":3,"pull":2,"roll":3}', 'Horror/Awe Factor 13. In addition to attribute bonuses: +2 on Perception Rolls, +3 initiative, +4 strike, +1 parry, +3 automatic dodge in water and on land, +2 pull punch, +3 roll with impact, +6 to save vs Horror Factor. Cannot do a power bite, kick or tail swipe. Each single or paired shot from the shoulder guns uses one of the rider''s melee attacks unless the steed is firing for itself.', 'Equivalent skills: Land Navigation 65%, Tailing 60% on land (+5% underwater), Underwater Navigation 85%. Picks up spoken languages quickly (65%); understands Lemurian and Oceanic at 80%.', 'Swims at 90%, breathes water and air without limit, Nightvision 1,000 feet (305 m), fine day and underwater sight, half damage from cold, heals 3D6 an hour (about 180 a day). Depth tolerance four miles (6.4 km). Two Stonecaster cannons, one grown into each shoulder, with a short-range ion blaster above each. All four fire forward only, through a 45 degree arc up and down, and feed on the steed''s own P.P.E. The rider triggers them by telepathy or a signal such as three taps on the neck; a steed whose rider is down, dead or dismounted can fire them itself. Stonecasters hold 60 shots and regain one a minute at a stone pyramid, nexus or ley line, one an hour elsewhere, or a mage can refill one at once with 60 P.P.E. Ion blasters hold 30 shots and regain one a minute at those places, one every three hours elsewhere, or all at once for 30 P.P.E. The rider sits high on the neck and must lean to see past the head, leaving a large blind spot on the far side.', NULL, NULL, '15-20 feet (4.6 to 6.1 m) tall from head to toes and 17-22 feet (5.2 to 6.7 m) long from snout to rump; the tail is 30-33 feet (9.1 to 10 m) long; 7-10 feet (2.1 to 3 m) wide at the shoulders', '1-2 tons; males tend to be 20% larger than females', '1D6x10+40 years', 'Wherever Lemurians live, above all their cities, gardens and outposts. The ocean is home, and reefs and gardens bring out its friendlier side; it also does very well ashore and likes to explore and hunt on islands and in coastal forests.', 'Chiefly Lemurians, who made it, and Ichthyleans; humans and aquatic D-Bees may also use one. Gets on with other serpents and tolerates most other War Steeds. Wary of people and most creatures other than Lemurians and Ichthyleans, and treats most large fish and mammals, people included, as possible threats.', 'Sharks and large marine predators, sea serpents, sea monsters, humanoids and the enemies of Lemuria', 'No O.C.C.; the newest steed of the Lemurian Gene-Mages, in service for only four years and well rated in combat by Oceanic Guardsmen and Serpent Hunters; also a strong draft animal. Value: 500,000-650,000 credits trained; the section says a steed that reaches the open market often brings 50% to 200% more. Hide is useless for armor; the spines alone can be made into spikes, stabbing weapons, picks or spearheads (1D6 M.D. each). The meat cannot be eaten.', 'A heavily armored mount with a giant seahorse''s frilled head, a horse''s body as thick-set as a bulldog''s, massive plated legs and a long serpent tail, golden brown with black, white and gold-flecked markings. It is closer to a slow living tank than to the other swift steeds, and its armor costs it speed and agility. Disposition: stoic and calm under heavy fire, bold and combative, loyal to its rider and its own kind but aloof, sparing with affection and indifferent to everyone else.', 'Rifts World Book 32: Lemuria p.199-201'),
('shadow-serpent', 'Shadow Serpent', 'monster', 'rifts', 0, 'Wild: mostly Diabolic (20%), Miscreant (30%) or Anarchist (30%). Raised by good Lemurians as War Steeds: Scrupulous (20%), Unprincipled (35%) or Anarchist (40%)', '{"IQ":"1D4+8","ME":"1D6+6","MA":"1D6+6","PS":"1D6+24","PP":"1D6+11","PE":"2D6+10","PB":"2D6+10","Spd":"1D6+18"}', NULL, NULL, '4D6x10+100', '1D6x10+PE', NULL, 'Available as an NPC sea serpent villain or a Lemurian War Steed. I.Q. is human-like but ruled by animal instinct; P.S. and P.E. are supernatural. Spd is on land (15 mph/24 km); Spd in water is 2D6+46 (50 mph/80 km or 43 knots). Full speed lasts 30 minutes per P.E. point, then at least five hours of rest; a leisurely pace lasts one hour per P.E. point. P.P.E. is 1D6x10 plus the P.E. number, plus 2D6 per level of experience. M.D.C. by location: Head 1D6x10+120; Legs, Front (2) 1D6x10+60 each; Legs, Rear (2) 2D4x10+80 each; Serpent Tail 3D6x10+120; Tail Blade (1; tip) 1D6x10+180; Main Body 4D6x10+100. Shadow M.D.C. (special): +120 M.D.C. while in darkness, lost only in daylight or bright light covering the whole serpent (three or more Globe of Daylight spells or several headlights; one flashlight or small Globe is not enough). On S.D.C. worlds: 1D6x10+40 Hit Points, 4D6x10 S.D.C. (+100 in darkness) and Natural A.R. 16. Average level of experience: 1D8 for NPCs or as the G.M. wishes; uses the Dragon Experience Table.', NULL, 12, '{"attacks":4,"initiative":1,"strike":6,"parry":4,"pull":5,"roll":2}', 'All bonuses: +3 on Perception Rolls in darkness only, +1 initiative, +6 strike, +4 parry, +5 automatic dodge in darkness or shadow, +5 pull punch, +2 roll with impact, +1 to save vs psionics and illusions, +3 to save vs magic and poison, +5 to save vs Horror Factor. Vulnerability to light: bright light strips its shadow powers and bonus M.D.C., and blinding effects (Blinding Flash, camera flashes, bright sunlight) last twice as long on it. It can act in daylight but must shade its eyes with a hand or its tail, losing one attack and suffering -2 to strike, parry and dodge.', 'R.C.C. equivalent skills: Camouflage 55%, Detect Ambush 65%, Detect Concealment 60%, Escape Artist 60%, Land Navigation 80%, Lore: Demons and Monsters 50%, Lore: Sea Creatures 70%, Prowl 50% (+25% when Shadow Melding), Tailing 60% (+20% in darkness or from shadows), Track Animals 65%, Track and Hunt Sea Creatures 80%, Underwater Navigation 90%. All improve +1% per level of experience. Magically understands and speaks all languages.', 'Natural swimmer 90%, half damage from cold, breathes air and water, sharp hearing and a good nose. Nightvision 4,000 feet (1219 m), even through total and unnatural darkness, but weak sight in light: 400 feet (122 m), or twice that when the light is low. Heals 2D6 M.D.C. each melee round, 4D6 in total darkness. Depth Tolerance: 7 miles (11.2 km). Blade Tail (special): the final 4-6 feet (1.2 to 1.8 m) of the prehensile tail is a bone blade with stegosaur-style spikes along its upper edge. Shadow Meld: as the spell but stronger, since it slips partway into the shadow dimension. Echolocation and sonar work against it at half skill with half bonuses (a Lemurian''s crude echolocation penalty goes from -1 to -4 to strike, parry and dodge). In darkness only thermal or infrared gear finds it, at -30%. Bright light ends the meld; a weak light such as a flashlight leaves it hard to see but open to sonar and echolocation. Size Metamorphosis (special): cannot take other shapes, but can shrink by up to 60%.', 'Starts with Cleanse (6), Cloak of Darkness (6), Fear (5) and Shadow Meld (10). Instinctively knows one new spell, chosen from levels 1-3 of Spell Invocations, at each new level of experience.', 'None', '20-30 feet (6.1 to 9.1 m) long from snout to rump, plus a tail of 25 to 30 feet (7.6 to 9.1 m)', '8 to 12 tons', '1D6x100+800 years', 'The dark: night waters and the depths of the abyss. Hunting brings it to the surface at night after fish, animals and humanoids in and out of the water, cattle, villagers and sailors; some raid coastal settlements or ships.', 'None as such in the wild, where it hunts alone or in small groups of 1D4+1; some side with evil magic users and dark forces. War Steeds are friends of Lemurians, Ichthyleans, Merans and friends of Lemuria, do not as a rule hunt humanoids or sentient beings, and can be strongly loyal to their rider.', 'Regards most people and animals as prey. Wild ones hate creatures of light and anyone who radiates or wields light (War Steeds only dislike and distrust them). Treats other sea serpents, monsters and dragons as rivals. A pirate band is rumored to raise Anarchist or evil ones as mounts, pets and assassins.', 'No O.C.C.; an NPC villain or a Lemurian mount, not a player character. A player character''s steed should be 1st or 2nd level. Reared from youth by Lemurians it becomes a loyal, talking partner that still needs its rider as a conscience. Value: 300,000-400,000 credits tamed as a steed, half that as an attack or guard animal. Hide is useless for armor; teeth become arrowheads, knives and war clubs; the tail blade can be made into a giant sword, propeller blade, rudder or ram prow. The meat cannot be eaten.', 'A jet black sea serpent with big black, blue-black or charcoal scales, glowing yellow cat-like eyes, webbed and clawed hands and feet, and a spiked tail. Often mistaken for a dragon, it is a duller and weaker cousin: a creature of magic with a few spells that lives like a wild beast. It eats fish and squid but prefers sharks, whales, dolphins, humans and D-Bees, toying with prey and striking from ambush. Disposition: sneaky, clever and cunning, a deceitful and self-serving predator by instinct.', 'Rifts World Book 32: Lemuria p.201-203'),
('thrall-sea-serpent', 'Thrall Sea Serpent', 'monster', 'rifts', 0, 'Principled (45%), Scrupulous (35%) or Unprincipled (15%); few are darker', '{"IQ":"1D4+7","ME":"1D6+15","MA":"1D6+17","PS":"1D4+30","PP":"1D6+15","PE":"1D6+15","PB":"1D6+8","Spd":"2D4+48"}', NULL, NULL, '3D6x10+120', '6D6+15', NULL, 'Lemurian War Steed, also called the Hunter Serpent and Royal Serpent. I.Q. is high animal intelligence, short of sentient cetaceans; P.S. and P.E. are supernatural. Spd is running (36 mph/57.6 km or 31 knots); double in water (72 mph/115 km or 62 knots); both rise 50% along a ley line. Full speed lasts one hour per P.E. point, then at least three hours of rest; a leisurely pace is indefinite. M.D.C. by location: Head 2D6x10+220; Fins (2, top) 5D6+20 each; Legs, Front (2) 1D6x10+90 each; Legs, Rear (2) 1D6x10+100 each; Tail 3D6x10+150; Main Body 3D6x10+120.', NULL, 15, '{"attacks":4,"initiative":3,"strike":3,"parry":3,"dodge":2,"pull":5,"roll":2}', 'Horror/Awe Factor 15. Four attacks per melee running, swimming or fighting on all fours, six in its cobra stance on land. In addition to attribute bonuses: +2 on Perception Rolls, +3 initiative, +3 strike with most attacks (+5 with the tail), +3 parry (+4 with the tail), +2 automatic dodge in water and on land, +5 pull punch, +2 roll with impact, +6 to save vs Horror Factor, +2 to save vs illusions and mind control, +5 to save vs poison and disease. The Power Bite counts as two melee attacks; no power tail or claw strike. Vulnerability: so fearless and loyal that it may take on hopeless odds, run foolish risks and die beside its rider.', 'R.C.C. equivalent skills: Land Navigation 75%, Tailing 75% (underwater only), Prowl 45% (underwater only), Track and Hunt Sea Creatures 80%, Underwater Navigation 90%. Picks up spoken languages quickly (75%); understands Lemurian and Oceanic at 90%.', 'Swims at 98%, breathes water and air without limit, Nightvision 1,000 feet (305 m), fine day and underwater sight, half damage from cold, heals 3D6 an hour (about 200 a day). Depth Tolerance: 8 miles (12.8 km). Chemoreceptors (special): taste and smell keen enough to follow prey underwater, read the salt and poison content of water and pick up blood as a shark does, out to one mile (1.6 km); names a chemical, toxin or creature at 50% and tracks at 70% (+10% for its rider or a blood trail). Crude Echolocation System (special): senses large objects by the echoes of its own sounds, far less exactly than a whale or bat, halving penalties for blindness or unseen foes. Ultrasonic Communication (special): hears ultrasound and produces it, like the Inaudible Frequency Transmission implant, to talk underwater with cetaceans, Lemurians and other Thralls. Cobra stance: on land it rears 30+ feet (9.1 m) high on its hind legs to weave, parry, claw and bite.', NULL, NULL, '35-40 feet (10.6 to 12.2 m) long from snout to rump plus 22-28 feet (6.7 to 8.5 m) of tail; stands 12-15 feet (3.6 to 4.6 m) on all fours and 30+ feet (9.1 m) reared up; body 5-6 feet (1.5 to 1.8 m) across, 10-12 feet (3 to 3.6 m) wide at shoulders and hips; head 4-5 feet (1.2 to 1.5 m) long and 4 feet (1.2 m) wide', '5-8 tons; males tend to be 15% larger than females', '1D6x10+75 years', 'Lives and fights beside Lemurians wherever they are, above all in their cities, gardens and outposts. The ocean is home, in any of Earth''s oceans, and now and then coasts and deep lakes. Some have gone wild in remote parts of the Pacific Rim and Indian Ocean.', 'Lemurians and their allies. Wild ones live alone, in pairs, in family groups of 3-8, or with cetacean pods and other sea serpents, and enjoy the company of animals and people.', 'The Milu, the Lord of the Deep, large marine predators, sea serpents, sea monsters, humanoids and the enemies of Lemuria', 'No O.C.C.; the first steed the Gene-Mages ever made and still much liked by Scouts, Serpent Hunters and Oceanic Guardsmen. A hatchling is usually given to a young Serpent Hunter (at times a Guardsman, Gene-Mage or royal) who raises it for life; the rider sits on the neck above the forelegs. Should its partner die, it has a 01-40% chance of refusing food and starves. Value: 350,000-600,000 credits trained; the section says a steed that reaches the open market often brings 50% to 200% more. Hide is useless for armor; only the teeth are worked, into daggers, spikes, spearheads and jewelry. Nobody buys the meat.', 'A sea-going answer to the tyrannosaur: a huge head and jaws able to bite a great white in two, short clawed limbs, and a long round body ending in a whip-like tail. Its leathery hide is crimson, orange or red-brown with dark patches and a pale belly. Swift and nimble at sea, it looks a slow target ashore until it rears up like a cobra. Disposition: ferocious and fearless in battle, roaring to frighten foes, yet a playful, affectionate puppy with its rider, whom it guards and never leaves.', 'Rifts World Book 32: Lemuria p.203-205'),
('tiger-serpent', 'Tiger Serpent', 'monster', 'rifts', 0, 'Any; wild ones are considered Anarchist or evil, animalistic predators. Lemurian-trained ones are usually Scrupulous (15%), Unprincipled (20%) or Anarchist (40%)', '{"IQ":"1D4+6","ME":"1D6+16","MA":"1D6+11","PS":"1D4+25","PP":"1D6+16","PE":"1D6+14","PB":"1D6+16","Spd":"2D4+25"}', NULL, NULL, '3D6x10+220', '2D4x10+PE', NULL, 'Also called Tiger Python and Striped Death. I.Q. is high animal intelligence, short of sentient cetaceans; P.S. and P.E. are supernatural. Spd is running/slithering (20 mph/32 km); double in water (40 mph/64 km or 34 knots); both rise 50% along a ley line. Full speed lasts one hour per P.E. point, then half speed for another 2D4 hours before it must rest five hours; a leisurely pace is indefinite. P.P.E. is 2D4x10 plus the P.E. number. M.D.C. by location: Head 2D4x10+120; Fins (many) 4D6 each; Legs, Front (2) 1D6x10+80 each; no rear legs; Main Body & Tail 3D6x10+220. On S.D.C. worlds: 2D6x10 Hit Points, 2D6x10 S.D.C. and Natural A.R. 15.', NULL, 14, '{"attacks":4,"initiative":5,"strike":3,"parry":4,"dodge":2,"pull":3,"roll":4}', 'In addition to attribute bonuses: +3 on Perception Rolls, +5 initiative, +3 strike, +4 parry, +2 dodge, +4 roll with impact, +2 disarm, +3 pull punch, +8 vs Horror Factor, +1 vs psionics and mind control, +6 to save vs disease. The power claw strike is printed without an attack cost; no power bite or tail strike. Cannot take a cobra stance. Vulnerability: so fearless and loyal that it may take on hopeless odds, run foolish risks and die beside its rider.', 'Equivalent skills: Climbing 85%/60% (at half running Spd), Prowl 60% (+15 underwater), Land Navigation 80%, Tailing 90% (underwater and on land), Tracking people 65% (on land only), Track and Hunt Sea Creatures 85%, Underwater Navigation 90%. Picks up spoken languages quickly (75%); magically understands all languages at 70% but cannot speak.', 'Natural swimmer 95%, breathes air and water without limit, Nightvision 1,000 feet (305 m), fine daylight sight and hearing, half damage from cold, depth tolerance 6 miles (9.6 km), heals 3D6 an hour (about 200 a day). Camouflage: its striped scales add +5% to Prowl, or to hiding amid seaweed or fallen trees, in water of shallow to medium depth. Lightning Quick Strike or Dart Attack: lunges as far as 15 feet (4.6 m) from cover, or from where it stands, to bite, claw or seize prey and haul it into the water; +2 to strike and it counts as a surprise or sneak attack. Venomous Bite: mouth bacteria force anyone bitten to save vs poison at 14 or better. Failure brings cramps and sore joints within 12 hours: -20% running and swimming speed, -1 attack, -2 to strike, parry and other combat moves, -20% on physical skills, for 2D6 hours. Then save again at +2; each further failure costs 1D4 Hit Points (2D4 for an M.D.C. being) and 3D6 more hours of penalties, until a save succeeds or a cure is given (medicine or antibiotics work in 1D4 hours, magic and psionics at once).', 'None', 'None', '40-60 feet (12.2 to 18.3 m) long from snout to tail tip; body 2-3 feet (0.6 to 0.9 m) in diameter, tapering along the tail; 5-6 feet (1.5 to 1.8 m) wide at the shoulders; stands 6-8 feet (1.8 to 2.4 m) tall on its front legs and rears up to 10-14 feet (3 to 4.3 m)', '3-6 tons; females are 20% larger than males', '2D4x10+100 years', 'Found wild and among Lemurians, wherever they live, as steeds and hunting animals. The ocean is home, in any of Earth''s oceans and seas, favoring reefs, seaweed forests and sunlit shallows; also coasts, swamps, jungle and rain forest ashore.', 'Lemurians and their allies. Wild ones are solitary, found alone or in mated pairs.', 'The Milu, the Lord of the Deep, large marine predators, sea serpents, sea monsters, humanoids and the enemies of Lemuria', 'No O.C.C.; a wild sea serpent, thought to come from another dimension, that Lemurians also train as a mount and hunting animal. The rider may sit anywhere along the body, normally just behind the shoulders. Value: 250,000-400,000 credits as a Lemurian War Steed. The hide makes medium armor that pirates and sea bandits prize for being tough yet light: 3D6+55 M.D.C., -7% to Prowl, climbing and other physical activity, selling for 50,000-65,000 credits.', 'A long snake-bodied serpent in orange or gold scales with black tiger stripes, a cat''s face, dark green eyes and webbed forefeet with retractable claws; it has no hind legs. A stealthy lone hunter on land and in the sea, it waits in weed or tall grass, or just under the surface like a crocodile, then lunges and drags prey under, or coils round it to drown or hold it. Disposition: cat-like, affectionate or disdainful as it pleases, sneaky, watchful and fond of the chase; as a steed it is notably loyal and obedient.', 'Rifts World Book 32: Lemuria p.205-207'),
('lemurian-leviathan', 'Leviathan', 'dragon', 'rifts', 0, 'Any, but most are Unprincipled (3%), Anarchist (30%), Aberrant (30%), Miscreant (20%) or Diabolic (15%)', '{"IQ":"1D4+6","ME":"1D6+16","MA":"1D6+13","PS":"3D6+40","PP":"1D6+13","PE":"2D6+13","PB":"1D6+4","Spd":"2D6+38"}', NULL, NULL, '1D6x1000', '1D4x100', 'MEx2', 'M.D.C. by location: Head 4D6x100 +50 per century of life; Front Flippers (2) 2D4x100 each; Rear Mid-Flippers (2, smaller) 1D4x100 each; Rear Flippers (2, smallest) 2D6x10 each; Tail (1, long) 3D6x100 +30 per century of life; Main Body 1D6x1,000 +100 per century of life. A young Leviathan has half of every figure, rounded down. The mdc field is the Main Body dice without the per-century addition. I.S.P. is M.E. x2, plus 2D6 per level of experience (one level per 100 years of age). P.S. and P.E. are supernatural. I.Q. is about human average, but cunning and perceptive. Spd 2D6+38 is swimming (about 32 mph/51 km or 27.8 knots); crawling on dry land is Spd 1D6+9 (around 8 mph/13 km). No S.D.C.-world figures are printed.', NULL, 18, '{"attacks":5,"initiative":3,"strike":6,"parry":4,"dodge":4,"pull":5,"roll":5}', 'Five physical attacks per melee, or two physical and three fire breath attacks, or any combination. +3 on Perception Rolls, +3 on initiative, +6 to strike, +4 to parry and dodge underwater (half on dry land), +5 to pull punch and bite, +5 to roll with impact, +8 to save vs possession and mind control, +5 to save vs magic, +10 to save vs poison, impervious to Horror Factor. Hand to hand damage as per Supernatural P.S. (42-50 on average). Power bite and full speed ram each count as two attacks. Vulnerability: its arrogance, fearlessness, aggression and sheer size sometimes work against it.', 'Non-player character monster skills: Astronomy and Navigation 90%; Languages: Cetacean, Dragonese, Lemurian, Milu and Oceanic, all at 87%, and two Earth languages of choice at 70%; Lore: Demons and Monsters 60%; Lore: Sea Creatures 80%; Prowl 50% (+10% in dark waters, not applicable on land); Tailing 70%; Track and Hunt Sea Animals 87%; Underwater Navigation 90%. Skills improve +2% per level of experience. Average level: one per hundred years of life, 2D4 for a typical NPC; uses the Dragon Experience Table.', 'Swims at 92%, hears keenly, has Nightvision to 2,000 feet (610 m) and breathes air or water alike. Fire and heat cannot hurt it; cold and electricity do half. Magically speaks and understands every language at 85%. Regenerates 4D6 M.D.C. each melee round. Fire breath (special): twice per melee round, either a 90 degree cone reaching 60 feet (18.3 m) for 5D6 M.D. to everyone in it, or a single-target stream reaching 150 feet (45.7 m) for 1D4x10 M.D.; ranges are halved underwater, where the blast still boils through to burn. It may instead vent superheated steam with the same shapes for 4D6 S.D.C. (cone) or 1D4x10 S.D.C. (stream), which it does as a warning. Chemoreceptors (special): tracks prey by taste and smell at 70% +2% per level, reads salt content and toxicity, tastes blood like a shark, and identifies chemicals, toxins or particular creatures from a scent trail at 50% +5% per level. Electromagnetic sense (special), 2,000 feet (610 m): sees the whole light spectrum including infrared and ultraviolet, body heat, thermoclines, the planet''s magnetic field (its underwater compass) and the nerve and muscle electricity of living things, so most invisible creatures are visible to it and total darkness is no handicap. Magic sense (special): sees and senses P.P.E. as a Ley Line Walker does.', 'None. Leviathans neither learn nor cast magic, though they respect it.', 'Minor Psychic. Meditation (0), Mind Block (4), Sense Magic (3), Sense Time (2) and Telepathy (4). I.S.P.: M.E. x2, +2D6 per level of experience (per 100 years of age).', '100-130 feet (30.5 to 39.6 m) from snout to rump, plus a tail of 60-90 feet (18.3 to 27.4 m). Clawed front flippers 50-60 feet (15.2 to 18.3 m) each, 150 feet (45.7 m) across fully extended; middle flippers about half that, rear flippers about 12 feet (3.6 m). Body 50-60 feet (15.2 to 18.3 m) wide with flippers folded; head 28-33 feet (8.5 to 10 m) wide and 10-15 feet (3 to 4.6 m) tall.', '60 to 90 tons', '2D6x100+800 years; full size and maturity at 100 years. Can hibernate for decades when food or magic energy is scarce. A female bears one live young every 100 years for her first 1,000 years.', 'The deep ocean, alone, often laired at or near an underwater volcano for the warmth. Rises to shallower water, the surface and even dry land to hunt fish, animals, humans and D-Bees.', 'None in the usual sense. Lemurians alone talk with them regularly and hold a shaky, tentative friendship; some Leviathans will fight the Milu, the undead and the Lord of the Deep''s creatures when asked. Serpent Hunters may ride one if it permits.', 'Treats nearly everything smaller as prey: sea monsters, sea serpents, War Steeds and people. Feuds with the Minions of Splugorth, despises the Metzla, and hunts dragons, hatchlings above all. Dislikes the Milu and the Lord of the Deep''s minions but leaves the Lord himself alone.', 'Not available to players; the stat block is headed as a Non-Player Character monster. Value: hide enough for a suit of non-environmental body armor with 1D6x10+90 M.D.C. (-10% to Prowl and movement) that sells for 80,000 to 120,000 credits; teeth are worked into blades, spearheads, staves, art and jewelry; the flesh cannot be eaten.', 'A colossal six-flippered sea monster thought to be a primordial dragon native to Earth and older than humankind; perhaps a hundred exist. Each is solitary, vain and sure it rules the ocean, eating serpents, whales, War Steeds and sailors as it pleases and sometimes sinking ships for sport. It is less clever than a true dragon and uses no magic, yet it hunts young dragons to prove itself their better. Lemurians win its tolerance by flattery and nerve, and their Serpent Hunters receive Leviathan Bio-Armor by stepping inside its closed jaws. Roughly two dozen have agreed to help Lemuria against the Milu and similar forces.', 'Rifts World Book 32: Lemuria p.208-210'),
('ghost-dragon', 'Ghost Dragon', 'dragon', 'rifts', 1, 'Any, though most are Anarchist (35%), Diabolic (15%), Miscreant (30%) or Aberrant (10%); a hatchling can start at any alignment', '{"IQ":"2D6+9","ME":"2D6+5","MA":"2D6+5","PS":"2D6+9","PP":"2D6+5","PE":"2D6+9","PB":"2D6+9","Spd":"2D6+7"}', NULL, NULL, '2D6x10+100', '1D6x10', '1D4x10+ME', 'The rolled figures are the HATCHLING''s. Hatchling: P.P.E. 1D6x10 plus 10 per level of experience; I.S.P. 1D4x10 + M.E., +2D4 per level; Spd 2D6+7 is running, doubled when swimming or in Ghost Flight; on S.D.C. worlds 5D6+7 Hit Points, 2D6x10+25 S.D.C., Natural A.R. 8. Adult: I.Q. 2D6+12, M.E. 2D6+14, M.A. 2D6+12, P.S. 3D6+20, P.P. 2D6+10, P.E. 2D6+10, P.B. 2D6+12, Spd 4D6+10 running, 1D6x10+100 flying or swimming; M.D.C. 4D6x100+1,300, +1D4x1,000 for an ancient; P.P.E. 1D4x100; I.S.P. 3D4x10 + M.E., +5 per level; Horror Factor 14; on S.D.C. worlds 3D6x10+40 Hit Points, 2D6x100+100 S.D.C., Natural A.R. 12. P.S. and P.E. are supernatural.', NULL, 10, '{"attacks":4,"initiative":1,"strike":2,"parry":1,"dodge":1,"pull":2,"roll":2}', 'Hatchling: four physical attacks per melee or two by breath weapon; +1 to initiative, +2 to strike, +1 to parry and dodge, +2 to pull punch, +2 to roll with impact, +3 to save vs Horror Factor and +1 on all other saving throws. Adult: eight physical attacks per melee, or two by magic, or up to four breath weapon attacks; +3 to Perception Rolls, +2 to initiative, +4 to strike, +3 to parry and dodge, +5 to pull punch, +3 to roll with impact, +7 to save vs Horror Factor and +2 on all other saving throws. All in addition to attribute bonuses. No power tail strike or power bite. Vulnerabilities: in Ghost Form it ignores most physical attacks, but weapons that harm ghosts and Entities work, dragon-slaying magic weapons do half their dragon damage, psionic attacks do full damage, and other magic weapons and spells do half damage for one third the duration; magic that summons or wards against spirits, ghosts and Entities holds it at bay only while ethereal. In physical form everything except cold harms it.', 'R.C.C. Skills (Hatchling): Advanced Math (+20%), Basic Math (+25%), Barter (+15%), Computer Operation (+10%), Land Navigation (+10%), Literate in Dragonese/Elven (+20%), Lore: Demons and Monsters (+30%), Lore: Faerie & Creatures of Magic (+20%), Prowl (+20%), Seduction (+20%), Underwater Navigation (+20%), plus four skill selections from Communication, Rogue, Technical, Wilderness and Weapon Proficiencies only. Level of experience: 2D4 for adult NPCs, 1D4 for hatchlings.', 'Sees the invisible, Astral Travelers, Entities and Alien Intelligence essences included; Nightvision reaches 800 feet (244 m) and color vision is excellent. Speaks and understands all languages by magic at 90% and turns invisible at will. Heals 1D4x10 M.D.C. a minute. Cold of any kind, magical M.D. cold too, does nothing to it. Teleport Self 80% (+15% to a well-known place); Dimensional Teleport 32% +4% per level. Needs no air and shrugs off both ocean pressure and vacuum; depth tolerance unlimited in either form. Breath weapon, P.P.E. Leech (special): once per melee round, a white mist of 5 foot (1.5 m) radius placed up to 50 feet (15.2 m) away strips 2D6 P.P.E. from each victim; mages and creatures of magic who control their P.P.E. lose nothing on a save vs magic of 14 or better. The dragon keeps what it takes for one minute per level and may spend it on its own spells. Ghost Form (special): it has only three shapes besides its own, each lasting six hours per level: a pale human-looking person with white, blue or green hair (no smaller than a cat, no bigger than itself), a physical miniature of itself down to half size, and an intangible ghost. The ghost walks through walls and solid matter but not magic or psionic energy fields, is see-through rather than invisible (it cannot turn invisible), and in mist, fog or water goes unseen until 10 feet (3 m) away. As a ghost it cannot attack or harm anyone physical, even with psionics; each switch between ghost and solid must be held for one full melee round (15 seconds) and costs no P.P.E., with no daily limit. Ghost Flight (special): as a ghost it runs, swims and flies at twice its normal Spd, up to two miles (3.2 km) high. Slay Ghosts and Entities: in Ghost Form its claws, teeth and psionics can strike spirits, Astral Travelers, Entities and Alien Intelligence essences; killing an Entity lets it eat the P.P.E., restoring 1D4x10 M.D.C., though that energy cannot power spells.', 'Hatchling: understands magic from birth but knows no spells at level one; can learn magic and can use Techno-Wizard, Biomancy and other magic weapons and devices (see Rifts Ultimate Edition p.156 for dragon hatchling rules). Adult: one area of magic, Ocean Magic (30%), Wizard/Spell Invocations as a Ley Line Walker (30%) or Necromancy (40%), and likely knows 3D6+10 spells from it; avoids the Warlock and Shifter O.C.C.s.', 'Master Psychic. Hatchling: Commune with Spirits (6), Machine Ghost (12), Mind Block (4), Sense Magic, Sense Time (2) and three powers from the Sensitive category; one additional at levels 4, 8, 12 and 16, and Empathic Transmission (6) at level 8. I.S.P. 1D4x10 + M.E., +2D4 per level. Adult: all Sensitive powers plus Empathic Transmission (6) and Radiate Horror Factor (8). I.S.P. 3D4x10 + M.E., +5 per level.', '20-24 feet (6.1 to 7.3 m) long from snout to rump, plus 10-15 feet (3 to 4.6 m) of tail; 7-9 feet (2.1 to 2.7 m) tall and 4-6 feet (1.2 to 1.8 m) wide at the shoulders', '3-5 tons', '1D6x1,000+2,000 years; some reach 10,000', 'Ocean depths, above all sunken ships, ship graveyards, battlefields, ocean ley line triangles and Dead Pools, though one can turn up anywhere. Some kill the living to stock their lairs with corpses and wrecks.', 'Evil and Anarchist ones take the Milu, the Lord of the Deep, Minions of Splugorth, the undead, demons, pirates, slavers, Necromancers and other selfish or evil beings as henchmen and associates. They avoid their own kind.', 'Other dragons, their own species included, are rivals. Evil and selfish ones treat heroes and good people as dupes and food. Entities are their natural prey. Serpent Hunters hunt them.', 'A hatchling may be a player character: a hatchling player character begins at level one and follows the dragon hatchling rules on p.156 of Rifts Ultimate Edition. This row rolls the hatchling; adult and ancient figures are for NPCs. Also called the Spectral Dragon or Sea Mist Dragon.', 'A pale white, long-bodied dragon of the eastern kind with short limbs, a crown of horns, pupil-less white eyes, a beard and feeler mustache, a mane down its spine and a fish-like tail tipped with fur; belly and hair are light gray, blue or green. A newcomer to Rifts Earth, it eats carrion and the entities that gather around death, so it haunts wrecks, battlefields and Dead Pools, hoards sunken treasure and baits adventurers with it. It will happily kill and let the bodies ripen for a few days. Scheming and treacherous, it sides with necromancers and Lemuria''s enemies far more often than with heroes.', 'Rifts World Book 32: Lemuria p.211-213'),
('hydros-dragon', 'Hydros Dragon', 'dragon', 'rifts', 1, 'Any, but tend to be Principled (35%), Scrupulous (30%), Unprincipled (10%) or Anarchist (10%)', '{"IQ":"2D6+6","ME":"2D6+4","MA":"1D6+12","PS":"2D6+18","PP":"2D6+6","PE":"2D6+12","PB":"2D6+3","Spd":"2D6+10"}', NULL, NULL, '1D6x100', '2D6x10', '1D6x10+ME', 'The rolled figures are the HATCHLING''s. Hatchling: P.P.E. 2D6x10 plus 2D6 per level of experience; I.S.P. 1D6x10 + M.E., +10 per level; Spd 2D6+10 is crawling like a snake on land, 6D6+30 swimming; on S.D.C. worlds 180 Hit Points, 2D6x10+25 S.D.C., Natural A.R. 10. Adult: I.Q. 2D6+12, M.E. 2D6+15, M.A. 2D6+12, P.S. 2D6+28, P.P. 2D6+10, P.E. 3D6+10, P.B. 4D6+6, Spd 1D6+18 on land (roughly 15 mph/24 km), 1D6x10+90 swimming (75-80 mph/120 to 128 km or 65 to 69 knots) without tiring; M.D.C. 1D6x1,000+800, +1D6x1,000 for an ancient; P.P.E. 1D6x100+180; I.S.P. 3D6x10 + M.E., +10 per level; Horror Factor 14; on S.D.C. worlds 4D6x10+100 Hit Points, 3D6x100+200 S.D.C., Natural A.R. 14. P.S. and P.E. are supernatural.', NULL, 10, '{"attacks":4,"initiative":1,"strike":2,"parry":1,"dodge":1,"pull":2,"roll":2}', 'Hatchling: four physical or psionic attacks per melee, or two by magic, or any combination; +1 on Perception Rolls (+2 to anything involving water), +1 to initiative, +2 to strike, +1 to parry and dodge, +2 to pull punch, +2 to roll with impact, +3 to save vs Horror Factor and +1 on all other saving throws. Adult: seven physical or psionic attacks per melee or four by magic; +2 on Perception Rolls (+5 to anything involving water), +2 to initiative, +3 to strike and parry, +1 to dodge (+4 to automatic dodge underwater), +5 to pull punch, +4 to roll with impact, +6 to save vs Horror Factor and +2 on all other saving throws. All in addition to attribute bonuses. Vulnerability: M.D. plasma and magic fire do double damage; it dislikes fire and heat.', 'R.C.C. Skills (Hatchling): Art (+30%), Computer Operation (+15%), Dowsing (+30%), Firefighting (+20%), Gemology (+20%), Land Navigation (+12%), Literate in Dragonese/Elven (+20%), Lore: Demon and Monster (+30%), Mathematics: Basic (+25%), Philosophy (+20%), Pilot: Sail Boats (+20%), Pilot: Water Scooters (+10%), Pilot: Water Skiing and Surfing (+40%), Prowl (+10% in water only), Underwater Navigation (+20%), plus four skill selections from Aquatic, Communication, Domestic, Science, Technical and Wilderness only. Level of experience: 2D4 for adult NPCs, 1D4 for hatchlings.', 'Sees the invisible, Astral Travelers, Entities and Alien Intelligence essences included; Nightvision reaches 800 feet (244 m) and color vision is excellent. Speaks and understands all languages by magic at 90% and turns invisible at will. Heals 1D4x10 M.D.C. a minute. Cold of any kind, magical M.D. cold too, does nothing to it. Teleport Self 50% +3% per level (+20% to a well-known place); Dimensional Teleport 24% +4% per level. Needs no air and shrugs off both ocean pressure and vacuum; depth tolerance unlimited. Its claws are real silver. Breath weapon, Cold (special): an icy mist reaching 120 feet (36.6 m) for 3D6 M.D. (5D6 M.D. from an adult), one melee attack per blast. Metamorphosis (special): any animal or legged humanoid from rabbit size up to its own size, for three hours per level. Metamorphosis: Water (special): becomes living water. On land it is a puddle that slips under doors and through vents, grates, drains and pipes at half its running speed. Submerged it cannot be found by sonar, nightvision, sound, heat sensing or even see the invisible. As water no physical attack touches it, and it can make no attack of any kind, psionics included, until solid again. Chemoreceptors (special): tracks by taste and smell at 76% +2% per level, reads salt content and toxicity, tastes blood like a shark, and identifies chemicals, toxins or particular creatures from a scent trail at 60% +2% per level. Quick Turns and Stops (special): halts instantly and reverses within tight underwater spaces. Senses magnetic north as a dolphin does. Whisker-like feelers around the mouth probe in darkness.', 'Hatchling: understands magic from birth but knows no spells at level one; can learn magic and can use Techno-Wizard, Biomancy and other magic weapons and devices (see Rifts Ultimate Edition p.156 for dragon hatchling rules). Adult: one area of magic, Ocean Magic (40%), Wizard/Spell Invocations as a Ley Line Walker (30%) or Whale Songs (30%), and likely knows 3D6+16 spells from it; avoids the Warlock and Shifter O.C.C.s and dark magic such as Necromancy.', 'Master Psychic. Hatchling: Empathy (4), Meditation (0), Mind Block (4) and five Hydro-Psionic abilities of choice (see the Spouter O.C.C.); +1 new Hydro-Psionic ability at each new level, Hydrokinesis (Super-Psionic) at level 4 and P.P.E. Shield at level 8. I.S.P. 1D6x10 + M.E., +10 per level. Adult: all Hydro-Psionic abilities plus the Super-Psionic powers Group Mind Block (22), Hydrokinesis (varies), Mind Bolt (varies) and P.P.E. Shield (30). I.S.P. 3D6x10 + M.E., +10 per level.', '36-50 feet (10.9 to 15.2 m) long', '12-20 tons', '1D6x1,000+2,000 years; some reach 9,000', 'Ocean depths, especially coral reefs and other living, beautiful places, but anywhere is possible. Equally at ease on land outside deserts, the arctic included; many hide their lair and hoard somewhere remote and frozen.', 'Heroes and beings of good alignment in general. Several are on friendly terms with Lemuria. Gets on well with Merans, dolphins and whales.', 'The Milu, the Lord of the Deep, Minions of Splugorth, Ghost Dragons, the undead, vampires, demons, pirates, slavers, Necromancers and anyone who enslaves or kills innocents. Fears fire, so it distrusts fire-breathing dragons, fire creatures, fire mages and Bursters.', 'A hatchling may be a player character: a hatchling player character begins at level one and follows the dragon hatchling rules on p.156 of Rifts Ultimate Edition. This row rolls the hatchling; adult and ancient figures are for NPCs. Also called the Water Dragon or Aqua Dragon.', 'A metallic silver-blue dragon with a silver belly, strong webbed forelimbs ending in genuine silver claws, mouth tusks, whisker feelers and, in place of hind legs, a tapering snake tail, so it is often taken for a sea serpent. Bright, gentle and moved by beauty, it loathes cruelty and regularly fights beside Lemurians and other heroes against the undead and supernatural evil. In battle the mild creature turns into a roaring fury. It serves nobody as a mount, yet has carried trusted heroes on its neck or behind its shoulders.', 'Rifts World Book 32: Lemuria p.215-216'),
('octo-dragon', 'Octo Dragon', 'dragon', 'rifts', 1, 'Any, though most are Diabolic (25%), Miscreant (40%), Aberrant (10%) or Anarchist (15%)', '{"IQ":"2D6+8","ME":"2D6+8","MA":"2D6+4","PS":"2D6+20","PP":"3D6+8","PE":"3D6+3","PB":"2D6+3","Spd":"3D6"}', NULL, NULL, '2D4x100', '2D4x10', '1D6x10+ME', 'The rolled figures are the HATCHLING''s. Hatchling: P.P.E. 2D4x10 plus 2D6 per level of experience; I.S.P. 1D6x10 + M.E., +2D4 per level; Spd 3D6 is slithering or crawling on its tentacles, swimming Spd 1D6+18 (20 mph/32 km or 17 knots) without tiring; on S.D.C. worlds 240 Hit Points, 2D6x10+80 S.D.C., Natural A.R. 9. Adult: I.Q. 2D6+16, M.E. 2D6+16, M.A. 2D6+8, P.S. 2D6+32, P.P. 2D6+16, P.E. 2D6+16, P.B. 1D6+6, Spd 3D6+10 slithering or crawling (15 mph/24 km), swimming Spd printed as 2D6+20 ''for an average swim speed of 2D6+36'' (around 30 mph/48 km or 26 knots) without tiring; M.D.C. 2D4x1,000+1,600, +1D4x1,000 for an ancient; P.P.E. 2D4x100+160; I.S.P. 2D6x10+16 + M.E., +10 per level; Horror Factor 15; on S.D.C. worlds 5D6x10+160 Hit Points, 3D6x100 S.D.C., Natural A.R. 12. P.S. and P.E. are supernatural.', NULL, 11, '{"attacks":4,"initiative":1,"strike":2,"parry":4,"dodge":1,"pull":2,"roll":2}', 'Hatchling: four physical attacks per melee round or two by magic; +1 to initiative (+2 in water), +2 to strike, +4 to parry and disarm, +4 to entangle, +1 to dodge, +2 to pull punch, +2 to roll with impact, +3 to save vs Horror Factor and +1 on all other saving throws. Adult: nine physical or psionic attacks per melee round or four by magic; +1 on Perception Rolls, +4 to initiative (+6 in water), +8 to strike and parry, +8 to disarm and entangle, +3 to dodge, +6 to pull punch, +2 to roll with impact, +8 to save vs Horror Factor and +2 on all other saving throws. All in addition to attribute bonuses. Vulnerabilities: ordinary fire does half its damage as M.D. (a 4D6 S.D.C. fire does 2D6 M.D.), and M.D. plasma, fire and magical fire do double damage. Hates captivity and rages, thrashing and bellowing, until exhausted.', 'R.C.C. Skills (Hatchling): Camouflage (+25%), Climbing (+30%), Escape Artist (+30%), Gemology (+20%), Intelligence (+10%), Interrogation (+20%), Land Navigation (+14%), Literate in Dragonese/Elven (+10%), Lore: Demons and Monsters (+20%), Mathematics: Basic (+15%), Pilot: Sail Boats (+20%), Prowl (+20%), Tailing (+20%), Underwater Navigation (+20%), plus five skill selections from Aquatic, Communication, Rogue, Technical, Wilderness and W.P. only. Level of experience: 2D4 for adult NPCs, 1D4 for hatchlings.', 'Sees the invisible and sees clearly through murky water; Nightvision reaches 500 feet (152 m) and color vision is excellent. Speaks and understands all languages by magic at 85% and turns invisible at will. Heals 1D4x10 M.D.C. a minute. Cold of any kind, magical M.D. cold too, does nothing to it. Teleport Self 48% +2% per level (+10% to a well-known place); Dimensional Teleport 16% +4% per level. Needs no air and shrugs off both ocean pressure and vacuum; depth tolerance unlimited. Eight prehensile tentacles and a prehensile tail grab, hold, carry and climb. Breath weapon, Ink Cloud (special): in air a dense black cloud filling 30x30x30 feet (9x9x9 m) for 1D4 melee rounds; underwater it covers twice the area for the same time. Anyone inside fights blind (-10 to strike, parry, dodge and every other combat move) until out of it, and because it is magical ink rather than smoke, infrared, passive nightvision goggles and Nightvision are all useless. Camouflage Quick Change (special): shifts skin color and pattern to match its surroundings in one melee action, as often as it likes, for +10% to Prowl and Tailing. Chemoreceptors: taste sensors in the mouth read small changes in salinity and water chemistry; chemicals are named from their taste at 72% +1% per level, and prey is tracked by taste at 72% +2% per level out to one mile (1.6 km). Metamorphosis (special): any animal or humanoid from wolf size up to its own size, two arms and two legs unless the copied creature has more limbs (eight at most), for two hours per level.', 'Hatchling: understands magic from birth but knows no spells at level one; can learn magic and can use Techno-Wizard, Biomancy and other magic weapons and devices (see Rifts Ultimate Edition p.156 for dragon hatchling rules). Adult: one area of magic, Wizard/Spell Invocations as a Ley Line Walker (90%), Ocean Magic (6%), or Necromancy or other dark magic (4%), and likely knows 3D6+16 spells from it; avoids magic that links it to another being, including the Warlock and Shifter O.C.C.s.', 'Master Psychic. Hatchling: Death Trance (1), Meditation (0), Mind Block (4) and five Physical psionic powers; +1 new Physical power at each new level, plus Radiate Horror Factor (8) at level 12. I.S.P. 1D6x10 + M.E., +2D4 per level. Adult: all Physical psionic powers plus the Super-Psionic power Radiate Horror Factor (8). I.S.P. 2D6x10+16 + M.E., +10 per level.', '30-40 feet (9.1 to 12.2 m) long from the snout to where the tentacles end, plus 90-100 feet (27.4 to 30.5 m) of tail; head 8-10 feet (2.4 to 3 m) across; each tentacle 30-40 feet (9.1 to 12.2 m) long', '30-50 tons', '1D6x1,000+1,600 years; some reach 9,000', 'Ocean depths anywhere. Many carve out a petty tyranny above or below the waves, or raid and terrorize coastal settlements. Several live in or around Atlantis.', 'Evil and Anarchist ones count Davey Jones, the Milu, the Lord of the Deep and the Splugorth and their minions as associates; six to twelve seem to serve the Lord of the Deep as generals or elite assassins. Undead, demons, pirates, slavers and evil mages become henchmen, slaves and worshipers. They avoid their own kind.', 'Evil ones despise Hydros Dragons, Sand Dragons, Lemurians (Serpent Hunters most of all), creatures of light and heroes. Other dragons, their own species and Ghost Dragons especially, are rivals. Mortals are slaves, worshipers, toys and food.', 'A hatchling may be a player character: a hatchling player character begins at level one and follows the dragon hatchling rules on p.156 of Rifts Ultimate Edition. This row rolls the hatchling; adult and ancient figures are for NPCs. Also called the Tentacle Dragon or Tyrant Dragon. A dragon-ruled city-state holds 4D6x100 people, and most Octo Dragons keep 3D4 evil henchmen as managers, spies and enforcers.', 'More giant eel than dragon: a long serpent body and huge head, jaws with a double row of sword-sized teeth, spines along two thirds of the back, eight octopus arms where legs or wings would be, and a tail ending in a great blade. Its finely scaled skin changes color like an octopus, resting at brownish gray over pink. A slow swimmer next to other sea dragons. Other dragons sense it as one of their own, though some think it an escaped creation of the Lord of the Deep. Short-tempered and savage, most are tyrants over frightened island or undersea folk; the few good ones are still quick to violence.', 'Rifts World Book 32: Lemuria p.216-218'),
('sand-dragon', 'Sand Dragon', 'dragon', 'rifts', 1, 'Any, but tends to be Scrupulous (20%), Unprincipled (25%) or Anarchist (30%)', '{"IQ":"2D6+8","ME":"2D6+6","MA":"3D6+6","PS":"3D6+10","PP":"2D6+5","PE":"2D6+9","PB":"2D6+4","Spd":"3D6+6"}', NULL, NULL, '1D6x100', '1D6x10+50', '1D6x10+ME', 'The rolled figures are the HATCHLING''s. Hatchling: P.P.E. 1D6x10+50 plus 2D6 per level of experience; I.S.P. 1D6x10 + M.E., +1D6+2 per level; Spd 3D6+6 is running, swimming Spd 3D6+30 (averaging 30 mph/48 km or 26 knots); on S.D.C. worlds 220 Hit Points, 2D6x10+30 S.D.C., Natural A.R. 11. Adult: I.Q. 2D6+12, M.E. 2D6+15, M.A. 2D6+12, P.S. 2D6+26, P.P. 2D6+10, P.E. 3D6+10, P.B. 3D6+7, Spd 3D6+38 running (around 35 mph/56 km), swimming Spd 4D6+60 (averaging 50 mph/80 km or 43 knots) without tiring; M.D.C. 1D6x1,000+1,200, +1D4x1,000 for an ancient; P.P.E. 1D6x100+400; I.S.P. 3D6x10 + M.E., +10 per level; Horror Factor 13; on S.D.C. worlds 5D6x10+120 Hit Points, 2D6x100 S.D.C., Natural A.R. 15. P.S. and P.E. are supernatural.', NULL, 10, '{"attacks":4,"initiative":1,"strike":1,"parry":1,"dodge":1,"pull":2,"roll":1}', 'Hatchling: four physical attacks per melee or two by magic; +1 on Perception Rolls (+2 to anything involving building), +1 to initiative, +1 to strike, +1 to parry and dodge, +2 to pull punch, +1 to roll with impact, +2 to save vs Horror Factor and +1 on all other saving throws. Adult: six physical attacks per melee or three by magic; +4 on Perception Rolls, +2 to initiative, +3 to strike and parry, +2 to dodge (+4 to automatic dodge underwater), +6 to pull punch, +3 to roll with impact, +4 to save vs Horror Factor and +2 on all other saving throws. All in addition to attribute bonuses. No power strike with claws or tail. Vulnerabilities: cold attacks do double damage. Trapped somewhere dark and ugly it becomes depressed: -1 attack per melee, no Perception Roll or initiative bonuses, -20% on skills, -1 on all combat moves and Spd reduced 20%.', 'R.C.C. Skills (Hatchling): Art (+20%), Calligraphy (+10%), Computer Operation (+20%), Dowsing (+30%), Excavation (+10%), Gemology (+20%), General Repair and Maintenance (+10%), Land Navigation (+16%), Literate in Dragonese/Elven (+30%), Mathematics: Basic (+25%), Military Fortifications (+15%), Philosophy (+15%), Pilot: Sail Boats (+20%), Pilot: Water Skiing and Surfing (+12%), Prowl (+10% in sand and water only), Underwater Navigation (+20%), Whittling and Sculpting (+25%), plus four skill selections from Aquatic, Communication, Domestic, Science, Technical and Wilderness only. Level of experience: 2D4 for adult NPCs, 1D4 for hatchlings.', 'Sees the invisible; Nightvision reaches 500 feet (152 m) and color vision is excellent. Speaks and understands all languages by magic at 90% and turns invisible at will. Heals 1D4x10 M.D.C. a minute. Fire of any kind, magical M.D. fire too, does nothing to it, and it enjoys bathing in lava. Teleport Self 60% +3% per level (+15% to a well-known place); Dimensional Teleport 28% +3% per level. Needs no air and shrugs off both ocean pressure and vacuum; depth tolerance unlimited. Breath weapon, Sand (special): a blast reaching 120 feet (36.6 m) for 3D6 M.D.; anyone without goggles, a face plate, armor or magic over the eyes is blinded until the grit is rinsed out with water, at -10 on strike, parry, dodge and every other combat move meanwhile. Metamorphosis (special): any animal or humanoid from fox size up to its own size, for three hours per level. Build with and Fortify Sand (special): it enchants a patch of sand, shapes its castle or sculpture, and finishes a ritual that hardens the work like M.D.C. concrete. Every 12 foot (3.6 m) section costs 25 P.P.E. and has 10 M.D.C. The work glows faintly, can be sensed by practitioners of magic within 1,000 feet (305 m), and stands for one week per level; on a ley line one month per level, and at a nexus or stone pyramid one year per level.', 'Hatchling: understands magic from birth but knows no spells at level one; can learn magic and can use Techno-Wizard, Biomancy and other magic weapons and devices (see Rifts Ultimate Edition p.156 for dragon hatchling rules). Adult: one area of magic, Ocean Magic (25%), Wizard/Spell Invocations as a Ley Line Walker (25%), Earth Warlock Magic (30%) or Temporal Magic (20%), and likely knows 2D6+14 spells from it; avoids dark magic such as Necromancy.', 'Master Psychic. Hatchling: Empathy (4), Object Read (6) and five powers of choice from either the Healing or the Sensitive category (pick one category); one new power from that same category at each new level, and Telemechanics at level 6. I.S.P. 1D6x10 + M.E., +1D6+2 per level. Adult: all Sensitive or all Healing powers, plus the Super-Psionic powers Hydrokinesis (varies), Telemechanics (10) and Telemechanics Mental Operation (12). I.S.P. 3D6x10 + M.E., +10 per level.', '20-30 feet (6.1 to 9.1 m) long from snout to rump, plus 30-40 feet (9.1 to 12.2 m) of tail', '18-30 tons', '1D6x1,000+2,000 years; some reach 10,000', 'Oceans and seas, beaches, deserts and any sand it can build in; curious and new to Rifts Earth, so it may be met wandering almost anywhere.', 'None as such; a loner happy building or exploring by itself. When it keeps company it favors heroes and good beings, and several are friendly with Lemuria.', 'None as such, though Lemuria''s foes assume it is one of theirs. The Milu, the Lord of the Deep, Shadow Serpents, Ghost Dragons, Octo Dragons, the undead, demons, pirates, slavers and Necromancers tend to hate it on sight. Dislikes cold and darkness and distrusts creatures and dragons of darkness.', 'A hatchling may be a player character: a hatchling player character begins at level one and follows the dragon hatchling rules on p.156 of Rifts Ultimate Edition. This row rolls the hatchling; adult and ancient figures are for NPCs. Also called the Sand Master, Earth Dragon or Castle Builder.', 'A bone white, cream or gold dragon with a green or red frill around the neck and matching fins down the spine. It is among the calmest of dragons: a sunbather and thinker that would sooner talk, explore and sculpt than fight, though it is dangerous when pushed. Its passion is building in sand, from small castles up to enormous magically bound works on beaches and the sea floor, and it takes any criticism of them badly. A practiced dimensional traveler only lately arrived, it owes nobody loyalty, finds Earth''s constant warfare baffling and regards Lemurians as near kindred.', 'Rifts World Book 32: Lemuria p.219-220');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('maui-tikitiki', 'Maui-Tikitiki', NULL, 'Leader and founder of the Mauian Order; also known as Maui-Mu, the Lone Traveler and the Dark Son of Lemuria', 'rifts', 'Lemurian', '15th level Shifter', 15, 'Aberrant evil (long ago Scrupulous)', '329; looks to be in his early 50s', '5 feet 8 inches (1.7 m)', '135 lbs (60.7 kg)', '{"IQ":25,"ME":29,"MA":22,"PS":22,"PP":23,"PE":24,"PB":9,"Spd":30}', 74, 53, NULL, 548, 79, NULL, NULL, '{"attacks":7,"initiative":5,"strike":9,"parry":8,"dodge":9,"roll":7,"pull":4,"damage":11}', 'P.B. 9 was once 21. Combat skill: Hand to Hand: Kapu Kuialua. +6 on Perception Rolls, +5 on initiative, +9 to strike, +8 to parry, +9 dodge, +7 to roll with impact, +4 to pull punch, +3 to disarm, +11 damage, +1 to body flip/throw, +1 body block/tackle, Critical Strike from behind on a Natural 17 to 20, +7 to save vs magic, +5 to save vs poisons, +9 to save vs psionics, +11 to save vs Horror Factor, 70% to Trust/Intimidate and 45% to Charm/Impress.', '[{"name":"Language & Literacy: Lemurian","pct":98},{"name":"Language & Literacy: Dragonese/Elven","pct":98},{"name":"Language & Literacy: English/American","pct":98},{"name":"Language & Literacy: Spanish","pct":98},{"name":"Language & Literacy: Chinese","pct":98},{"name":"Language: Cetacean","pct":98},{"name":"Language: Demongogian","pct":98},{"name":"Language: Faerie Speak","pct":98},{"name":"Language: Oceanic","pct":98},{"name":"Astronomy","pct":98},{"name":"Basic Mathematics","pct":98},{"name":"Advanced Mathematics","pct":98},{"name":"Computer Operation","pct":98},{"name":"Horsemanship: General","pct":98},{"name":"Horsemanship: Exotic","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Lore: Dimensions","pct":98},{"name":"Lore: Magic","pct":98},{"name":"Lore: Cattle and Animals","pct":98},{"name":"Lore: Sea Creatures","pct":98},{"name":"Lore: D-Bees","pct":98},{"name":"Lore: Faeries and Creatures of Magic","pct":98},{"name":"Undersea and Sea Survival","pct":98},{"name":"Underwater Navigation","pct":98}]', 'Printed as Skills of Note, all at 98%. Shifter ability Dimensional Sense 98%. Weapon Proficiencies: W.P. Blunt and W.P. Trident at 15th level; W.P. Sword and W.P. Knife at 6th level proficiency.', 'Everything common to Lemurians, with a supernatural amount of P.P.E. and deep knowledge of forbidden magic, chiefly Shifter, Ley Line and Temporal Magic.', '15th level Shifter. Shifter abilities: Dimensional Sense 98%, Dimensional Travel, Communication Rift, Dimensional Teleport Home (Rifts Earth), Sense Rifts and Familiar Link (Iki the Lemur). He has no link to the supernatural, but deals with the Splugorth and other dark gods, summons demons and supernatural beings to fight for him, and keeps powerful animals, sea monsters, sea dragons and sea serpents as minions, guards, mounts and pets. Favorite spells (P.P.E. cost): all Ley Line Magic spells, Animate and Control Dead (20), Annihilate (600), Armor of Ithan (10), Aura of Power (4), Banishment (65), Befuddle (6), Blinding Flash (1), Breathe without Air (5), Calling (8), Call Lightning (15), Calm Storm (200), Carpet of Adhesion (10), Circle of Travel (600), Cloud of Smoke (2), Compulsion (20), Constrain Being (20), Control and Enslave Entity (80), D-Step (50), Desiccate the Supernatural (50), Dimensional Portal (1,000), Dimensional Teleport (800), Dispel Magic Barrier (20), Distant Voices (10), Domination (10), Energy Disruption (12), Energy Sphere (120), Expel Demons (35), Forcebonds (25), Influence the Beast (12), Invisibility: Simple (6), Ley Line Transmission (30), Locate (30), Magic Pigeon (20), Magic Net (7), Magic Warrior (60), Metamorphosis: Animal (25), Metamorphosis: Insect (60), Meteor (75), Multiple Images (7), Mystic Alarm (5), Mystic Portal (60), Negate Magic (30), Phantom Mount (45), Plane Skip (65), Power Bolt (20), Protection Circle: Simple (45), Protection Circle: Superior (300), Repel Animals (7), Re-Open Gateway (180), Reality Flux (75), Reduce Self (20), Rift to Limbo (160), Rift Teleportation (200), Sanctum (390), See Aura (6), See the Invisible (4), Sense Evil (2), Sense Magic (4), Shadow Meld (10), Sheltering Force (20), Summon Ally (600), Summon and Control Animals (125), Summon and Control Canines (50), Summon Fog (140), Summon and Control Sea Serpents (350), Summon and Control Rain (200), Summon and Control Storms (300), Summon and Control Rodents (70), Summon Shadow Beasts (140), Sustain (12), Tame Beast (30), Teleport: Lesser (15), Teleport: Superior (600), Time Hole (210), Time Slip (20), Tongues (10), Trance (10), Turn Dead (6), Watchguard (10) and Wink-Out (20+). Temporal spells: Attune Object to Owner (30), Dimensional Pocket (20 or 140), Dimensional Envelope (60 or 380), Remote Viewing (45), See Dimensional Anomaly (30), Sense Dimensional Anomaly (30), T-Dep: Time Deprivation (20), Time Warp: Slow Motion (45+), Temporary Time Hole (100) and Time Warp: Fast Forward (75). Ocean Magic: Armor of Neptune (20), Coral Armor (10 or 45), Metamorphosis: Fish (50), Metamorphosis: Crustacean (60 or 120), Metamorphosis: Shark (90 or 160), Mystic Sea Horse (15), Strength of the Whale (20) and Summon Sea Friend (40).', 'Minor Psychic, 79 I.S.P. As per all Lemurians: Empathic Connection with Animals, Empathy (4), Mind Block (4), Object Read (6), See the Invisible (4), Speed Reading (2) and Telepathy (4).', NULL, NULL, 'Can get almost any Lemurian-made weapon. T-Club (Te Kauae Maro Muri-ranga-whenua, the Jawbone Club of Muri-ranga-whenua): a paddle-shaped Bio-Weapon with a very short handle, made by his ancestor; 3D6 M.D. in melee, double to temporal creatures and users of Temporal Magic (Temporal Wizards, Warriors and Raiders, Prometheans, Phase Adepts and Phase Mystics), and +1 to save vs any Temporal Magic. Guardian Staff: an octagonal stone-like staff, possibly a Rune Weapon, with eight gems in its head; 4D6 M.D. as a blunt weapon, 6D6 M.D. to supernatural foes and creatures of magic. Switching gems takes one action and each use counts as one of his attacks. Red: beam, 4D6 M.D., 4,000 feet (1,219 m). Orange: stream of fire, 5D6 M.D., 300 feet (91 m), not underwater. Yellow: telekinetic orb, 2D6 M.D., 1,000 feet (305 m). Green: orb to 200 feet (61 m) that grows plants or coral to entangle all within 12 feet (3.6 m); 16 or better to dodge, 1D4+3 melee rounds to get free; fired at a mortal humanoid or large mammal it instead gives 2D6+10 extra Hit Points or heals that much H.P./S.D.C.; lasts 2D4+3 melee rounds. Teal: soaking orb, 1D6x10 damage to vampires and 1D6x10 M.D. to Fire Elementals and other beings vulnerable to water, or puts out fire across a 12 foot (3.6 m) diameter. Blue: cold beam, 2D6 M.D., double to those vulnerable to cold or ice. Purple: orb of darkness that hides him and creates Horror Factor 12 up to 300 feet (91 m) away. Violet: beam that closes wounds, stops bleeding and purges poison, restoring 1D6 Hit Points, S.D.C. or M.D.C. per wound. Armor: Barnacle armor or magic.', NULL, 'A cold, calculating sociopath with no compassion and little regard for life, driven to gather power and to prove himself smarter and fitter to rule than any other Lemurian. He keeps a warped personal code of honor, despises ordinary Lemurians as pacifist sheep, and believes Lemurians ought to rule humans and D-Bees with him as King. Bent on exterminating True Atlanteans and Chiang-Ku dragons.', 'The Mauian Order (95% Lemurian) and its secret members inside Lemurian society; the Jungle Elves of South America. Can call on Biomancers, Ley Line Walkers, Ley Line Rifters, Mind Melters, Mystics, Stone Masters, Shifters, Temporal Raiders, Wizards and Wilderness Scouts, and on various dragons, the Minions of Splugorth and the Splugorth themselves; by rumor also dark gods and one or more Yama Kings.', 'True Atlanteans and Chiang-Ku dragons above all; the leadership of Lemuria, which he works to undermine', 'An aging, scarred Lemurian with shoulder-length white dreadlocks braided with seaweed and shells and a white beard tinged blue. Two centuries of roaming the Megaverse after power and forbidden magic made him a mighty Shifter and cost him his looks and, some say, his soul. He founded the Mauian Order, a terrorist cult hidden within Lemurian society, and is rumored to keep a base on Splugorth Atlantis under Lord Splynncryth''s protection. The Order is secretly hunting the Blade Eternal for him. His Familiar is a lemur named Iki.', 'Rifts World Book 32: Lemuria p.17-19'),
('davey-jones', 'Davey Jones', NULL, 'Master Vampire and General of the Milu; aliases Davey, David Jones, Duffy Jones, Duffy Jonah and David Jonah', 'rifts', 'Master Vampire of The Dark Warmth of Cold Death (formerly human)', '13th level Pirate, now a 300-year-old Master Vampire', 13, 'Diabolic', '300-year-old Master Vampire; looks 40', '6 feet (1.8 m)', '170 lbs (76.5 kg)', '{"IQ":14,"ME":11,"MA":24,"PS":23,"PP":17,"PE":14,"PB":11,"Spd":13}', NULL, NULL, 240, 30, NULL, NULL, 14, '{"attacks":7,"initiative":5,"strike":5,"parry":7,"roll":2,"pull":6}', 'P.S. and P.E. are Supernatural. Spd 13 running; 52 underwater (36 mph/57.6 km or 31 knots). Horror Factor 14 applies once opponents realize who and what he is. Seven hand to hand attacks. Bonuses (all included): +3 on Perception Rolls, +5 on initiative, +5 to strike, +7 to parry and disarm, +6 to pull punch, +5 to disarm, +2 roll with impact, +7 to save vs Horror Factor, 80% to evoke trust or intimidate. Impervious to all forms of mind control, possession, and magic sleep, paralysis and domination. Disarm is printed twice, at +7 and at +5. Vulnerabilities: the same as the Mahiki Milu, including S.D.C. weapons of wood or silver, Bio-Energy and sunlight.', '[{"name":"Language: English (Native)","pct":98},{"name":"Language: French","pct":98},{"name":"Language: Portuguese","pct":98},{"name":"Language: Dutch","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Ichthylean/Milu","pct":98},{"name":"Pilot: Sail Boats","pct":98},{"name":"Pilot: Sailing Ships","pct":98},{"name":"Barter","pct":98},{"name":"Brewing","pct":98},{"name":"Climbing","pct":98},{"name":"Dance","pct":98},{"name":"Disguise","pct":98},{"name":"Navigation","pct":98},{"name":"Impersonation","pct":98},{"name":"Palming","pct":98},{"name":"Pick Locks","pct":98},{"name":"Pick Pockets","pct":98},{"name":"Prowl","pct":98},{"name":"Public Speaking","pct":98},{"name":"Radio: Basic","pct":98},{"name":"Rope Works","pct":98},{"name":"Swimming","pct":98},{"name":"Underwater Navigation","pct":98},{"name":"Undersea Survival","pct":98},{"name":"Undersea Salvage","pct":98}]', 'Printed as Skills of Note, all at 98%; Boxing is in the same list. W.P. Knife, W.P. Sword, W.P. Handguns, W.P. Energy Pistols and W.P. Paired Weapons, all at 10th level proficiency.', 'Every power of the Mahiki Milu vampires (see that entry). In addition: Nightvision 2,000 feet (610 m), working in total darkness; immune to disease, toxins and poison; needs no air and ignores ocean pressure. Punches and physical blows, Mega-Damage weapons and M.D. energy attacks other than fire do nothing to him, and magic and magic weapons do half damage. Bio-Regenerates 2D6 M.D.C. per melee round. He can make new aquatic vampires, and he is the link between Rifts Earth and The Dark Warmth of Cold Death: destroy him and the Milu can create no more undead.', 'None of his own. Knows magic lore and tales of magic items, and owns and can use several magic items from his treasure hoard.', 'As per all vampires, nothing extra.', NULL, NULL, 'Favors pistols, revolvers and old flintlocks. The Slayer Flintlock: a TW weapon or similar, perhaps built for a Vampire Hunter. Range 120 feet (36.6 m); fires any bullet up to an 18 mm ball; each shot is one attack; holds six rounds, and for 20 P.P.E. it generates six silver bullets. The Dirge Cutlass: a silver magic sword doing 2D6 S.D.C. to mortals, 2D6 M.D. to most Mega-Damage beings and 5D6 M.D. to undead, demons, other evil supernatural beings and creatures vulnerable to sonic attacks; it hums in combat like a synthesized guitar. Armor: seldom worn, though he will consider it before a major battle; any armor that fits a human. Vehicles: commandeers ocean vessels when he wants one. Escort: at least four Mahiki Milu, 1D4+1 Milu (one of them a level 1D6+4 Necromancer) and 2D6 Zombie Servants; at the Locker, the City of Bones or on a cruise he adds 2D6+6 mortal servants and slaves.', NULL, 'Cruel and malicious, yet beguilingly charming, a gift his vampire powers sharpen and which he uses to fool heroes and recruit evil henchmen and partners. Happy to serve a dark god because he thinks himself a god and relishes the work. Above all a miser: no hoard is ever big enough, and greed pushes him into foolish risks.', 'Commands the Milu, Mahiki Milu and Zombie Servants on Rifts Earth, all of whom will sacrifice themselves to protect him; also manipulates, charms and hires mortal dupes, stooges and henchmen', 'The living in general, and Lemurians most of all', 'A pirate-era Londoner who drugged his tavern''s patrons and sold them as slave crew until surviving victims tortured him and made him walk the plank chained to an iron ball. Drowning, he pledged himself to any dark god, and The Dark Warmth of Cold Death remade him over centuries into its Master Vampire and the Milu''s demigod general. He always appears as a human in an 18th Century sea captain''s hat, long coat and cutlass; beneath it he is gaunt and gray, with a thick black beard and icy blue eyes. After seven attempts over nearly 200 years he built his Locker, a fortress, treasure vault and prison on the floor of the Indian Ocean, around which the Milu raised the City of Bones.', 'Rifts World Book 32: Lemuria p.158-162');
