-- Rifts World Book 32: Lemuria - its bestiary and its notable NPCs.
-- 33 creatures (migration 074) and 2 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~176-lemuria-creatures-and-npcs.sql
--
-- Written by scripts/bestiary-sql.mjs from 2 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.








-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 33 creatures are in' AS assertion, count(*) AS got, 33 AS want
  FROM creatures WHERE slug IN ('carnivorous-blue-fruit-tree', 'lemurian-ring-tailed-lemur', 'lemurian-aquatic-lemur', 'milu', 'mahiki-milu', 'blue-otter', 'death-hunter-fish', 'giant-sea-slug', 'ichthyosaur', 'jonahs-fish', 'kilmorans-eel', 'line-ray', 'mega-ray', 'narcassai-swordfish', 'saber-toothed-sea-lion', 'sea-dragon-turtle', 'storm-crab', 'terror-eel', 'twisted-treasure-seahorse', 'panther-shark', 'sea-lance', 'sea-saber', 'sea-whip', 'seal-serpent', 'serpent-seahorse', 'shadow-serpent', 'thrall-sea-serpent', 'tiger-serpent', 'lemurian-leviathan', 'ghost-dragon', 'hydros-dragon', 'octo-dragon', 'sand-dragon');
SELECT 'and 4 of them are playable' AS assertion, count(*) AS got, 4 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('carnivorous-blue-fruit-tree', 'lemurian-ring-tailed-lemur', 'lemurian-aquatic-lemur', 'milu', 'mahiki-milu', 'blue-otter', 'death-hunter-fish', 'giant-sea-slug', 'ichthyosaur', 'jonahs-fish', 'kilmorans-eel', 'line-ray', 'mega-ray', 'narcassai-swordfish', 'saber-toothed-sea-lion', 'sea-dragon-turtle', 'storm-crab', 'terror-eel', 'twisted-treasure-seahorse', 'panther-shark', 'sea-lance', 'sea-saber', 'sea-whip', 'seal-serpent', 'serpent-seahorse', 'shadow-serpent', 'thrall-sea-serpent', 'tiger-serpent', 'lemurian-leviathan', 'ghost-dragon', 'hydros-dragon', 'octo-dragon', 'sand-dragon');
SELECT 'all 2 notable NPCs are in' AS assertion, count(*) AS got, 2 AS want
  FROM notable_npcs WHERE slug IN ('maui-tikitiki', 'davey-jones');
SELECT 'the creatures carry 163 attacks' AS assertion, count(*) AS got, 163 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('carnivorous-blue-fruit-tree', 'lemurian-ring-tailed-lemur', 'lemurian-aquatic-lemur', 'milu', 'mahiki-milu', 'blue-otter', 'death-hunter-fish', 'giant-sea-slug', 'ichthyosaur', 'jonahs-fish', 'kilmorans-eel', 'line-ray', 'mega-ray', 'narcassai-swordfish', 'saber-toothed-sea-lion', 'sea-dragon-turtle', 'storm-crab', 'terror-eel', 'twisted-treasure-seahorse', 'panther-shark', 'sea-lance', 'sea-saber', 'sea-whip', 'seal-serpent', 'serpent-seahorse', 'shadow-serpent', 'thrall-sea-serpent', 'tiger-serpent', 'lemurian-leviathan', 'ghost-dragon', 'hydros-dragon', 'octo-dragon', 'sand-dragon');
SELECT 'and the notables 16' AS assertion, count(*) AS got, 16 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('maui-tikitiki', 'davey-jones');

